(window.GIM_TS=window.GIM_TS||{})["Nedarim.1"]={"from":24,"a":[["\u0003לאו אתה שומע הן! ואלא\u0004 תאמר שהוא כשיטת \u0003ר' יהודה\u0004 החלוק על ר' מאיר, אולם לשיטתו אין הדבר צריך להיאמר שהרי \u0003היינו רישא\u0004 \u0005[זהו\u0006 שכתוב \u0005בתחילה]\u0006 בפרק הקודם, שנאמר במשנה (שהעמדנו אותה כדעת ר' יהודה) שהאומר \"לחולין\" — הרי זה נדר!","ומשיבים: אכן, שיטת ר' יהודה היא, אולם \u0003איידי דקתני\u0004 \u0005[מתוך ששנה]\u0006 במשנתנו אחרי כן \u0003\"כבשר חזיר\", \"כעבודה זרה\", להכי קתני\u0004 \u0005[לכך,\u0006 מפני כן, \u0005שנה]\u0006 כדרך אגב גם \u0003\"חולין\"\u0004 עמהם, אף שאין הדבר צריך.","\u0003רבינא אמר, הכי קתני\u0004 \u0005[כך שנינו]:\u0006 \u0003ואלו\u0004 הם הדברים ה\u0003מותרין\u0004 לגמרי שאין בהם נדר כלל — הנודר \u0003\"כחולין\", \"כבשר חזיר\", \"כעבודה זרה\". ואי\u0004 \u0005[ואם]\u0006 \u0003לא תנא\u0004 \u0005[\u0006היה \u0005שונה]\u0006 \u0003חולין\u0004 כאן, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי למרות שמן התורה אין כאן נדר, מכל מקום עדיין \u0003בעי\u0004 \u0005[צריך]\u0006 הנדר \u0003שאלה,\u0004 שצריך הנודר להישאל לחכם ולמצוא היתר לנדרו.","ומקשים: \u0003ומי איכא לאסוקי על דעתא הכי\u0004 \u0005[והאם יש\u0006 מקום \u0005להעלות על הדעת כך,\u0006 פירוש כזה\u0005]?\u0006 \u0003הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנה בסוף]:\u0006 \u0003האומר לאשתו \"הרי את עלי כאימא\" — פותחין לו פתח ממקום אחר, מכלל\u0004 הדברים אתה למד שבמקרים שמנה ב\u0003רישא\u0004 \u0005[בתחילה]\u0006 \u0003לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003שאלה\u0004 כלל! \u0003אלא\u0004 צריך לחזור מדברי רבינא ו\u0003מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 כפי שהסברנו קודם שהמשנה כשיטת ר' יהודה היא, ו\u0003חולין ממילא נסבה\u0004 \u0005[הביא אותה],\u0006 כלומר, בדרך אגב הובאה לשון זו, להשלים את הדברים.","לגופם של הדברים שואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו],\u0006 מה המקור במקרא לכך שהמתפיס נדר בדבר האסור אינו נדר? ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"איש כי ידר נדר לה'\"\u0004 (במדבר ל, ג) וכוונתו — \u0003עד שידור בדבר הנדור,\u0004 כלומר, הוא נודר איסור על דבר, ותולה אותו בדבר שאיסורו בא מחמת נדר ולא בדבר האסור מעצמו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה דורש, אם כן \u0003אפילו\u0004 תלה נדרו \u0003בדבר האסור נמי\u0004 \u0005[גם כן]\u0006 יחול נדרו, \u0003דהא כתיב\u0004 \u0005[שהרי נאמר]\u0006 בהמשך הפסוק \u0003\"לאסר אסר על נפשו\"!\u0004 משמע שהוא אוסר משום דבר האסור. ודוחים: הכתוב \u0003\"לאסר אסר\" מבעי ליה לכדתניא\u0004 \u0005[נצרך לו לפי\u0006 הדרש \u0005ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003איזהו איסר האמור בתורה כו',\u0004 שנודר איסור על עצמו ומתפיסו באיסור שכבר חל עליו, וגם שם מדובר שאותו איסור שהוא תולה בו, מקורו בנדר.","שנינו במשנה: \u0003האומר לאשתו \"הרי את\u0004 עלי \u0003כאימא\"\u0004 — פותחין לו פתח ממקום אחר, ואף שאין בדבריו כלום, שהרי תלה נדרו בדבר האסור, מכל מקום צריך להישאל על כך לחכם ואין אומרים לו שאין זה נדר. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 ממה ששנינו במקום אחר: האומר לאשתו \u0003\"הרי את עלי כבשר אימא\",\u0004 או \u0003\"כבשר אחותי\",\u0004 או \u0003\"כערלה\",\u0004 או \u0003\"ככלאי הכרם\",\u0004 שהם איסורי הנאה — \u0003לא אמר כלום\u0004 ומשמע שאף אינו צריך להישאל לחכם על כך!","\u0003אמר אביי:\u0004 אין זו סתירה, ואפשר לפרש כך: \u0003לא אמר כלום — מדאורייתא\u0004 \u0005[מן התורה],\u0006 שאכן מדין תורה אין זה נדר, \u0003ו\u0004אולם מכל מקום \u0003צריך שאלה — מדרבנן\u0004 \u0005[מ\u0006דברי \u0005סופרים].\u0006 \u0003רבא אמר: הא\u0004 \u0005[זו,\u0006 הברייתא\u0005]\u0006 מדברת \u0003בתלמידי חכמים\u0004 והם יודעים שביטוי כגון זה אינו נדר, \u0003הא\u0004 \u0005[זו,\u0006 המשנה\u0005]\u0006 מדברת \u0003בעם הארץ,\u0004 שכדי שלא יבוא לזלזל בנדרים החמירו עליו שיצטרך להישאל במקרה זה אף שאין כאן באמת נדר.","\u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנודר\u0004 ומתפיס נדרו \u0003ב\u0004ספר \u0003תורה — לא אמר כלום,\u0004 כלומר, אין זה נדר כלל. \u0003ואמר ר' יוחנן: ו\u0004מכל מקום \u0003צריך שאלה לחכם\u0004 כדי להתיר אותו. \u0003ואמר רב נחמן: ו\u0004אם הוא \u0003תלמיד חכם אינו צריך שאלה.\u0004 ומכאן שבנדרים מסויימים מחמירים על עם הארץ שישאל לחכם, אף על פי שבאמת אין זה נדר."],["א \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הנודר בתורה — לא אמר כלום\u0004 ואין זה נדר. אבל אם נדר \u0003במה שכתוב בה,\u0004 מכיון שכתובים בה שמות ה' — הרי זה כנודר בשם ולכן \u0003דבריו קיימין.\u0004 נדר \u0003בה ובמה שכתוב בה — דבריו קיימין.\u0004","על הברייתא הזו תוהים: תחילה \u0003קתני\u0004 \u0005[שנה]\u0006 \u0003\"במה שכתוב בה\" — דבריו קיימין,\u0004 ואם כן, אם נדר \u0003\"בה ובמה שכתוב בה\" צריך\u0004 עוד \u0003למימר\u0004 \u0005[לומר]\u0006 שדבריו קיימים? והרי מובן הדבר, שהרי זה נכלל במה שאמרנו קודם!","\u0003אמר רב נחמן: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זו]\u0006 — \u0003דמחתא אורייתא אארעא\u0004 \u0005[שמונחת התורה על הארץ],\u0006 כלומר, במקום אחר, \u0003הא\u0004 \u0005[זו]\u0006 — \u0003דנקיט לה בידיה\u0004 \u0005[שמחזיק אותה בידו].\u0006 וכך הוא טעמם של דברים: אם התורה \u0003מחתא על ארעא\u0004 \u0005[מונחת על הארץ]\u0006 — \u0003דעתיה אגוילי\u0004 \u0005[דעתו על הגוילים],\u0006 כלומר, על גופו של הספר שהוא הקלף עצמו, וכשהוא נודר אז \"בתורה\" או אפילו אמר \"במה שבתוכה\", כוונתו היא על הספר המוחשי, והנודר בו אינו נדר, אלא אם כן אמר גם \"בה\" וגם \"במה שבתוכה\". אבל \u0003נקט לה בידיה\u0004 \u0005[מחזיק אותה בידו]\u0006 — \u0003דעתיה\u0004 \u0005[דעתו]\u0006 \u0003על האזכרות\u0004 \u0005[שמות ה']\u0006 \u0003שבה\u0004 ויש בכך משום נדר, שאם אמר \"במה שבתוכה\", כוונתו למה שכתוב בה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 כל הברייתא מדברת \u0003דמחתא\u0004 \u0005[ש\u0006היא \u0005מונחת]\u0006 \u0003על ארעא\u0004 \u0005[הארץ]\u0006 \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003דאף על גב דמחתא\u0004 \u0005[שאף על פי ש\u0006היא \u0005מונחת]\u0006 \u0003על ארעא\u0004 \u0005[הארץ]\u0006 \u0003כיון\u0004 ש\u0003אמר \"במה שכתוב בה\" — מהני\u0004 \u0005[מועיל]\u0006 כנדר. \u0003ו\u0004את לשון המשנה יש להסביר לפי סגנון \u0003\"זו ואין צריך לומר זו\" קתני\u0004 \u0005[שנה].\u0006 שהסביר תחילה דין אחד (\"במה שכתוב בה\") שיש בו חידוש, ואחר כך אמר דין פשוט יותר, וכאילו אמר: ואין צריך לומר כאשר נדר \"בה ובמה שכתוב בה\" שהדין כמו כן.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003כולה מציעתא נמי\u0004 \u0005[כל\u0006 הפיסקה \u0005האמצעית גם כן]\u0006 שאומר \"בה ובמה שכתוב בה\" ונדר הוא, מדובר \u0003דנקיט ליה בידיה\u0004 \u0005[שמחזיק אותה,\u0006 את התורה, \u0005בידו].\u0006 \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003כיון דנקיט ליה בידיה\u0004 \u0005[שמחזיק אותה בידו],\u0006 \u0003אף על גב דלא אמר\u0004 \u0005[אף על פי שאינו אומר]\u0006 \u0003אלא \"בה\"\u0004 ואינו מפרש \"במה שכתוב בה\" — הריהו \u0003כמאן דאמר\u0004 \u0005[כמי שאומר]\u0006 \u0003\"במה שכתוב בה\" דמי\u0004 \u0005[נחשב],\u0006 ולכן נאסר.","האומר \u0003\"קונם שאני ישן\",\u0004 שאוסר על עצמו בקונם לישון, או \u0003\"\u0004קונם \u0003שאני מדבר\",\u0004 או \u0003\"\u0004קונם \u0003שאני מהלך\",\u0004 או \u0003האומר לאשה \"קונם שאני משמשך\u0004 (מקיים איתך יחסי אישות) \u0003\"\u0004— \u0003הרי זה\u0004 נדר, ועובר \u0003ב\"לא יחל דברו\"\u0004 אם לא קיים את הנדר.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה הבאה: אמר \u0003\"קונם עיני בשינה היום אם אישן למחר\", אמר רב יהודה אמר רב: אל ישן היום, שמא ישן למחר,\u0004 ואז נמצא למפרע שעבר היום על הנדר. \u0003ורב נחמן אמר: ישן היום, ולא חיישינן\u0004 \u0005[ואין אנו חוששים]\u0006 \u0003שמא ישן למחר,\u0004 שהרי על היום לא היה בינתיים שום איסור, ולמחר, כיון שאסר עצמו בכך — יזהר ולא יישן. ומוסיפים: \u0003ומודה רב יהודה באומר \"קונם עיני בשינה למחר אם אישן היום\"\u0004 שאם רוצה \u0003שישן היום,\u0004 שבשנתו היום אין כל חשש איסור, אלא שעל ידי כך חל עליו איסור לישון למחר."],["\u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא מזדהיר\u0004 \u0005[נזהר]\u0006 אדם בקיום נדר, הרי זה דווקא \u0003בתנאה\u0004 \u0005[בתנאי],\u0006 כגון במקרה הראשון שהשינה למחרת היא רק תנאי שעל פיו חל האיסור למפרע — אין אדם נזהר בו, ויכול לבוא לכלל איסור. \u0003אבל באיסורא\u0004 \u0005[באיסור]\u0006 — \u0003מזדהר\u0004 \u0005[\u0006הוא \u0005נזהר],\u0006 ובמקרה שאמרנו שיש ממש איסור בשינה שביום השני — הרי הוא נזהר בדבר, ואין חוששים שיעבור. ומעתה מנסים להביא ראיה במחלוקת זו מן המשנה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003\"קונם שאני ישן\",\u0004 או \u0003\"שאני מהלך\",\u0004 או \u0003\"שאני מדבר\",\u0004 הרי זה נדר. ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהמשמעות היא בדיוק \u0003כדקתני\u0004 \u0005[כפי ששנה\u0006 במשנה\u0005],\u0006 יש לתמוה: וכי האומר \u0003\"שאני ישן\" מי הוי נדרא\u0004 \u0005[האם הוא נדר]\u0006 כלל? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003חומר בשבועות\u0004 מבנדרים, \u0003שהשבועות חלות על דבר שיש בו ממש ועל דבר שאין בו ממש, מה שאין כן בנדרים, ו\u0004מאחר ש\u0003שינה דבר שאין בו ממש הוא,\u0004 כיצד אם כן יכול הקונם לחול עליה! \u0003אלא\u0004 יש לומר שמדובר ש\u0003אמר: \"קונם עיני בשינה\",\u0004 ומאחר ועיניו דבר שיש בו ממש הם, לכן חל נדרו.","\u0003ו\u0004נברר עוד: \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003לא יהיב שיעורא\u0004 \u0005[נתן שיעור\u0006 לדבר\u0005]\u0006 ואסר עצמו בשינה לעולם, \u0003מי שבקינן ליה\u0004 \u0005[האם מניחים אותו]\u0006 שלא יישן \u0003עד דעבר\u0004 \u0005[שיעבור]\u0006 בעל כרחו על \u0003איסור \"בל יחל\"\u0004 כאשר יישן? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן:\u0004 מי שאמר \u0003\"שבועה שלא אישן שלשה ימים\",\u0004 כיון שאנו יודעים שאין אדם מסוגל לכך — אין מניחים לו שיעבור על השבועה, אלא \u0003מלקין אותו\u0004 משום שבועת שוא \u0003וישן לאלתר\u0004 (מיד). ואף כאן לא יחול הנדר כשלא קבע לו זמן! נמצא שאי אפשר לפרש את המשנה בצורה זו.","\u0003אלא\u0004 נאמר שהכוונה במשנה היתה ש\u0003אמר \"קונם עיני בשינה למחר אם אישן היום\",\u0004 שאסור לו לישון היום כדי שלא יעבור איסור \"בל יחל\" אם לא יישן מחר. אולם זה לא ניתן להיאמר, שכן \u0003הא אמרת\u0004 \u0005[הרי אומר אתה]\u0006 שבנדר כזה לדעת הכל אין מקפידים שלא יישן היום, כיון ש\u0003כל\u0004 דבר שהוא \u0003באסוריה, מזדהר\u0004 \u0005[באיסורו, נזהר]\u0006 ולא יעבור עליו למחרת, ואם כן, מדוע אסור לו לישון היום?","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שפירוש הדברים ש\u0003אמר \"קונם עיני בשינה היום אם אישן למחר\". ו\u0004מעתה \u0003אי לא ניים\u0004 \u0005[אם אינו ישן]\u0006 \u0003היום, כי ניים\u0004 \u0005[כאשר יישן]\u0006 \u0003למחר מאי\u0004 \u0005[מה]\u0006 \u0003\"בל יחל דברו\" איכא\u0004 \u0005[יש]\u0006 בכך? \u0003אלא לאו בדניים\u0004 \u0005[\u0006האם \u0005לא\u0006 מדובר כאן \u0005ב\u0006מי \u0005ש\u0006כבר \u0005ישן]\u0006 ומזהירים אותו שלא יישן מחר, כדי שלא יעבור משום \"בל יחל\" למפרע. \u0003אלמא איתיה דניים\u0004 \u0005[מכאן\u0006 ש\u0005ישנו\u0006 מצב \u0005ש\u0006בו הוא \u0005ישן\u0006 היום\u0005]\u0006 למרות הנדר, ואין חוששים שמא יישן גם מחר. \u0003ותיובתא\u0004 \u0005[ו\u0006הרי זו \u0005קושיה חמורה]\u0006 על \u0003רב יהודה\u0004 שאמר שאסור לישון היום כדי שלא יעבור על הנדר כאשר יישן למחר!","ודוחים: אין זו קושיה, \u0003כי קתני\u0004 \u0005[כאשר שנה\u0006 במשנה\u0005],\u0006 לא נאמר בה שמותר לו לכתחילה לישון, אלא \u0003דאי ניים\u0004 \u0005[שאם ישן]\u0006 היום, צריך להיזהר שלא יישן מחר, שאז יחול עליו האיסור.","\u0003רבינא אמר: לעולם\u0004 תפרש \u0003כדקתני\u0004 \u0005[כפי ששנה\u0006 בדיוק\u0005]\u0006 שאמר \"קונם שאני ישן\", ומה שהקשינו שאין נדר תופס בדבר שאין בו ממש — יש לומר שמעיקר הדין באמת אין זה נדר, \u0003ומאי\u0004 \u0005[ומה\u0006 משמעות\u0005]\u0006 לשון \u0003\"בל יחל\"\u0004 האמורה במשנה כאן — יש לפרש שהוא \u0003מדרבנן\u0004 \u0005[מדברי סופרים].\u0006 שאף שאינו נדר האוסרו מן התורה, מכל מקום אמרו חכמים שאסור לו לעבור על מה שאמר.","ושואלים: \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 איסור \u0003\"בל יחל\" מדרבנן\u0004 \u0005[מדברי סופרים]?\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003דברים המותרין\u0004 מן הדין \u0003ואחרים נהגו בהן איסור,\u0004 שכך מנהגם לאסור — \u0003אי\u0004 (אין) \u0003אתה רשאי להתירן בפניהם, שנאמר: \"לא יחל דברו\"\u0004 (במדבר ל, ג), שאם ינהגו היתר, יש בכך כעין חילול נדר. ואף שלא היה כאן נדר של ממש אלא רק מנהג, מכל מקום יש בכך משום \"לא יחל דברו\" מדברי סופרים.","ומנסים להביא ראיה אחרת נגד דעת רב יהודה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 אמר לאשתו \u0003\"\u0004קונם \u0003שאת נהנית לי\u0004 (ממני) \u0003עד הפסח אם תלכי לבית אביך עד החג\"\u0004 (חג הסוכות שאחריו), אם \u0003הלכה\u0004 לבית אביה \u0003לפני הפסח — אסורה בהנאתו עד הפסח,\u0004 שהרי עברה על התנאי שלו, וחל הנדר, ואסורה ליהנות לו.","ונדייק, אם \u0003הלכה לפני הפסח — אסורה,\u0004 אם \u0003לא הלכה — לא\u0004 אסורה. והרי התנאי שהתנה עימה היה עד לחג, ויש לחשוש שמא תלך לאביה לפני החג ותעבור למפרע על איסור הנדר. וקשה הדבר לשיטת רב יהודה האוסר!","\u0003אמר ר' אבא:\u0004 יש לפרש כך, אם \u0003הלכה לפני הפסח — אסורה\u0004 להנות ממנו, \u0003ו\u0004אם נהנתה ממנו, שעברה על הנדר — \u0003לוקה. לא הלכה\u0004 לפני הפסח הרי זו \u0003אסורה בעלמא\u0004 \u0005[בלבד]\u0006 שהרי לא חל עליה עדיין האיסור, אלא שיש לחשוש שמא תעבור על תנאו לאחר הפסח, ונמצא למפרע שעברה על איסור ההנאה ממנו.","ושואלים: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של אותה משנה: אם הלכה \u0003אחר הפסח —\u0004 הרי הוא \u0003ב\"בל יחל דברו\".\u0004 ונברר: \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר ש\u0003לא איתהני\u0004 \u0005[נהנתה]\u0006 \u0003לפני הפסח, מי איכא\u0004 \u0005[האם יש]\u0006 אפשרות שתעבור על \u0003\"בל יחל\"?\u0004 הרי לא עברה על הנדר! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כאן \u0003דאיתהני\u0004 \u0005[שנהנתה]\u0006 לפני הפסח, ואם הלכה אחר הפסח לפני החג — נמצא שעברה על הנדר. \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מיתהני\u0004 \u0005[שנהנית],\u0006 כלומר, שרשאית היא ליהנות למרות שאחר כך אפשר שתעבור על התנאי ותבוא לידי עבירה על הנדר,"],["\u0003ותיובתא\u0004 \u0005[וקושיה חמורה]\u0006 אם כן על דעת \u0003רב יהודה!\u0004","ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר שנינו\u0006 במשנה\u0005]\u0006 הרי זה \u0003דאי איתהני\u0004 \u0005[שאם נהנה]\u0006 בדיעבד \u0003הרי זה ב\"בל יחל דברו\",\u0004 ולא שנה שם שייהנה לכתחילה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003\"שאת נהנית לי עד החג אם תלכי לבית אביך עד הפסח\",\u0004 אם \u0003הלכה לפני הפסח — אסורה בהנאתו עד החג,\u0004 שהרי חל הנדר, \u0003ומותרת לילך אחר הפסח.\u0004","ונדייק מכאן: דווקא אם \u0003הלכה\u0004 לפני הפסח — \u0003אסורה,\u0004 אך אם \u0003לא הלכה — לא\u0004 אסורה, ומותרת להנות ממנו, ואין חוששים שמא תלך ותעבור ב\"בל יחל\". וקשה על רב יהודה שאומר שלא תעשה לכתחילה מעשה שיביא להחלת הנדר!","\u0003אמר רבא: הוא הדין\u0004 ש\u0003אפילו\u0004 אם \u0003לא הלכה\u0004 — \u0003אסורה,\u0004 אלא עדיין יש הבדל: אם \u0003הלכה\u0004 — \u0003אסורה ו\u0004אם נהנתה ממנו \u0003לוקה, לא הלכה — אסורה בעלמא\u0004 \u0005[סתם]\u0006 להנות ממנו, כדברי רב יהודה, מפני החשש שמא לא תקיים הנדר ותלך לבית אביה לפני הפסח.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על רב יהודה מברייתא: האומר \u0003\"ככר זו\u0004 אסורה \u0003עלי היום אם אלך למקום פלוני למחר\", אכל\u0004 את הככר היום — \u0003הרי זה ב\"בל ילך\"\u0004 מחר. הרי שמותר לו לאכול, ואין חוששים שמא ילך למחר!","ודוחים: מה הקושיה? \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 \u0003\"אוכל\"\u0004 (לכתחילה) את הככר? \u0003\"אכל\" קתני\u0004 \u0005[שנה],\u0006 והכוונה \u0003דכי\u0004 \u0005[שכאשר]\u0006 \u0003אכל הרי זה ב\"בל ילך\".\u0004","ושנינו בהמשך: \u0003הלך\u0004 ביום השני — \u0003הרי זה ב\"בל יחל דברו\".\u0004 ונדייק, שאמר בלשון בדיעבד \"הלך\", אבל \u0003מהלך,\u0004 כלומר, לכתחילה — \u0003לא.\u0004 ודבר זה נוח לדעת רב נחמן, שמותר לו לאכול היום ולהחיל את הנדר, ולכן אם אכל — אסור לו ללכת. אבל לשיטת רב יהודה, שאסור לו לאכול את הככר היום, נמצא שלא חל הנדר כלל. \u0003וקשיא\u0004 \u0005[וקשה]\u0006 על דברי \u0003רב יהודה!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב יהודה: הוא הדין דליתני\u0004 \u0005[ש\u0006היה יכול \u0005לשנות]\u0006 \u0003\"מהלך\",\u0004 אלא \u0003איידי דקתני רישא\u0004 \u0005[על ידי ששנה בתחילה]\u0006 \u0003\"אכל\"\u0004 בלשון עבר \u0003דלא מיתני ליה\u0004 \u0005[שאין יכול לשנות לו\u0006 כאן\u0005]\u0006 \u0003\"אוכל\",\u0004 שהרי לשיטת רב יהודה אסור לו לאכול, ולכל הדעות אינו צריך לכתחילה לאכול — משום כך שמר את הסגנון האחיד, ולכן \u0003תני סיפא\u0004 \u0005[שנה בסופה]\u0006 \u0003\"הלך\",\u0004 ולא שנה \"מהלך\". ונמצא איפוא שלא הצלחנו להוכיח כדברי אחד מן החולקים.","שנינו במשנה: \u0003האומר לאשה \"קונם שאני משמשך\", הרי זה ב\"בל יחל דברו\".\u0004 ושואלים: איך יכול הוא לאסור דבר זה על עצמו \u0003והא משתעבד\u0004 \u0005[והרי משועבד]\u0006 הוא \u0003לה מדאורייתא\u0004 \u0005[מן התורה]\u0006 לתשמיש \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שארה כסותה וענתה לא יגרע\"\u0004 (שמות כא, י) ו\"עונתה\" הוא החיוב לשמש איתה!","ומשיבים: אכן אם נדר בלשון זו אין הנדר קיים, אלא \u0003באומר \"הנאת תשמישך\u0004 אסורה \u0003עלי\", והא\u0004 \u0005[והרי]\u0006 \u0003לא קא ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003בתשמיש,\u0004 שהרי מסיבה זאת נדר את נדרו. וכיון שהנאת התשמיש הבאה לו ממילא, אסורה עליו, ובהנאה זו הוא אינו חייב, ומשום כך בפועל נאסר עליו התשמיש מחמת הנדר.","והרי זה כעין מה ש\u0003אמר רב כהנא:\u0004 אשה שנודרת ואומרת לבעלה \u0003\"תשמישי עליך\"\u0004 בקונם — \u0003כופין אותה ומשמשתו,\u0004 ומדוע — כיון \u0003דשעבודי משעבדת ליה\u0004 \u0005[ש\u0006היא \u0005משועבדת לו]\u0006 לתשמיש כחלק מחובות הנישואין. אבל אם אמרה בנדרה \u0003\"הנאת תשמישך עלי\" — אסור\u0004 לבעלה לשמש איתה, לפי \u0003שאין מאכילין לו לאדם דבר האסור לו,\u0004 וכיון שהיא נהנית מן התשמיש והיא אסרה על עצמה את ההנאה — הרי אסור עליו לכפות אותה לאיסור.","אמר \u0003\"שבועה שאיני ישן\",\u0004 או שאמר \u0003\"שאיני מדבר\",\u0004 או \u0003\"שאיני מהלך\" — אסור\u0004 בכל אלה. אמר \u0003\"קרבן לא אוכל לך\",\u0004 או אמר \u0003\"הא קרבן שאוכל לך\",\u0004 או \u0003\"לא קרבן לא אוכל לך\" —\u0004 בכל אלה \u0003מותר.\u0004"],["\u0003א גמרא\u0004 מבררים: כשיטת \u0003מני מתניתין\u0004 \u0005[מי היא משנתנו]\u0006 — לכאורה כשיטת \u0003ר' מאיר היא, דאי\u0004 \u0005[שאם]\u0006 תאמר שהיא כדעת \u0003ר' יהודה —\u0004 הלא ר' יהודה \u0003לא שני ליה\u0004 \u0005[שונה לו]\u0006 אם אמר \u0003\"קרבן\u0004 שאוכל לך \u0003\" ולא שני ליה\u0004 \u0005[שונה לו]\u0006 אם אמר \u0003\"הקרבן\u0004 שאוכל לך\u0003\",\u0004 שאין אלה ביטויים של נדר (אלא רק אם אמר \"כקרבן\"), ובמשנה משמע שרק אם יאמר \"הקרבן שאוכל לך\" יהיה מותר, אבל אם אמר \"קרבן שאוכל לך\" יהיה אסור.","ומקשים: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: אם אמר \u0003\"לקרבן לא אוכל לך\" — מותר. והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003\"לקרבן לא אוכל לך\" ר' מאיר אוסר, ואמר ר' אבא\u0004 בסיבת האיסור: \u0003נעשה כאומר \"לקרבן יהא, לפיכך לא אוכל לך\".\u0004 ונראה איפוא שאין המשנה אף כדברי ר' מאיר!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — ש\u0003אמר \"לקרבן\"\u0004 ובמקרה זה חל הנדר, \u0003הא\u0004 \u0005[זה]\u0006 — ש\u0003אמר \"לא לקרבן\",\u0004 שמשמעו: ש\u0003לא הוי\u0004 \u0005[יהיה]\u0006 \u0003קרבן קאמר\u0004 \u0005[אמר]\u0006 ובלשון זו אין בכך דין נדר כלל.","אמר \u0003\"שבועה לא אוכל לך\",\u0004 או \u0003\"הא\u0004 \u0005[זו]\u0006 \u0003שבועה שאוכל לך\",\u0004 או \u0003\"לא שבועה לא אוכל לך\" — אסור.\u0004","\u0003מכלל\u0004 לשון המשנה אתה למד שלשון \u0003\"הא שבועה שאוכל לך\" — \"דלא אכילנא\u0004 \u0005[שאינני אוכל]\u0006 \u0003\" משמע,\u0004 שהיתה כוונתו לומר: זו היא שבועה שאני אוסר עצמי אם אני אוכל. והכוונה היא שנשבע שלא יאכל. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במשנה: מיני \u0003שבועות\u0004 הן \u0003שתים\u0004 בסיסיות, \u0003שהן ארבע: \"שאוכל\" ו\"שלא אוכל\" \"שאכלתי\" ו\"שלא אכלתי\".\u0004 ומדייקים: \u0003מדקאמר\u0004 \u0005[ממה שאמר]\u0006 וחילק במשנה זו בלשון \"שאוכל\" וכנגדה \u0003\"שלא אוכל\", \"שאכלתי\" ו\u0004כנגדה \u0003\"שלא אכלתי\", מכלל\u0004 הדברים אתה למד כי לשון \u0003\"שאוכל לך\" — \"דאכילנא\u0004 \u0005[שאני אוכל]\u0006 \u0003\" משמע!\u0004 וכיצד אנו אומרים במשנתנו שאסור באכילה אם הוא אומר \"שבועה שאוכל\"?","\u0003אמר אביי: \"שאוכל\" שתי לשונות משמע\u0004 ופירוש המלה תלוי בהקשר הדברים בה נאמרה, כיצד? אם \u0003היו מסרבין\u0004 (מפצירים) \u0003בו לאכול ואמר: \"אכילנא אכילנא\u0004 \u0005[אוכל אני, אוכל אני]\u0006 \u0003\"\u0004\u0003ותו\u0004 \u0005[ועוד]\u0006 מוסיף ואומר: \u0003\"שבועה שאוכל\"\u0004 — הרי שבועה זו \u0003\"דאכילנא\u0004 \u0005[שאני אוכל]\u0006 \u0003\" משמע,\u0004 שנשבע לאכול. \u0003אבל\u0004 אם \u0003אמר\u0004 קודם: \u0003\"לא אכילנא לא אכילנא\u0004 \u0005[אינני אוכל, אינני אוכל]\u0006 \u0003\"\u0004\u0003ותו\u0004 \u0005[ועוד]\u0006 הוסיף \u0003ואמר: \"שבועה שאוכל\",\u0004 אז \u0003\"דלא אכילנא\u0004 \u0005[שאינני אוכל]\u0006 \u0003\" קאמר\u0004 \u0005[אמר].\u0006 כלומר, התכוון לחזק דבריו בשבועה, שנשבע שלא יאכל.","\u0003רב אשי אמר:\u0004 לשון \u0003\"שאוכל\"\u0004 של \u0003שבועה\u0004 שאמרנו במשנתנו יש לשנות \u0003\"שאי אוכל\u0004 \u0005[שאין אני אוכל]\u0006 \u0003\" קאמר\u0004 \u0005[אמר].\u0006 ושואלים: \u0003אם כן\u0004 שבפירוש נשבע שלא לאכול, \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, \u0003מאי למימרא\u0004 \u0005[מה\u0006 יש \u0005לומר]\u0006 בכך? הלא נשבע בפירוש שלא יאכל! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מיקם לישנא היא דאיתקיל ליה\u0004 \u0005[העמדת,\u0006 יישור \u0005הלשון הוא שנתקל לו]\u0006 שאפשר היה לחשוב שרצה לומר \"שבועה שאוכל\" ונתקל בלשונו ואמר \"שאי אוכל\", על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאם אמר \"שבועה שאי אוכל\" כוונתו שאין הוא אוכל.","ומסבירים את שיטות הפירוש הללו: \u0003אביי לא אמר טעם\u0004 (הסבר) המשנה \u0003כרב אשי,\u0004 מדוע — ש\u0003לא קתני\u0004 \u0005[שנה\u0006 במשנה\u0005]\u0006 \u0003\"שאי אוכל\"\u0004 אלא שנינו במשנתנו \"שאוכל\".","\u0003ורב אשי נאדי\u0004 \u0005[נדד,\u0006 לא קיבל\u0005]\u0006 \u0003מן טעם\u0004 הסברו של \u0003אביי,\u0004 כי \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 כי \u0003\"שלא אוכל\" נמי\u0004 \u0005[גם כן]\u0006 \u0003משמע שתי לשונות.\u0004 כגון אם \u0003היו מסרבין\u0004 (מפצירים) \u0003בו לאכול ואמר: \"לא אכילנא לא אכילנא\u0004 \u0005[אינני אוכל, אינני אוכל]\u0006 \u0003\", ואמר נמי\u0004 \u0005[גם כן]\u0006 \u0003\"שבועה\", בין\u0004 שאמר בלשון \u0003\"שאוכל\" בין\u0004 שאמר \u0003\"שלא אוכל\" — הדין\u0004 \u0005[\u0006לשון \u0005זה]\u0006 \u0003\"אכילנא\u0004 \u0005[אוכל אני]\u0006 \u0003\"\u0004\u0003משמע\u0004 ש\u0003אמר.\u0004 ומה שאמר \"שלא אוכל\" יש לפרשו כלשון תמיהה: וכי נשבעתי שלא אוכל? אלא ודאי אוכל אני.","\u0003ואיכא לתרוצה נמי לישנא\u0004 \u0005[ואפשר ליישב אותה גם כן\u0006 את \u0005הלשון]\u0006 \u0003\"שבועה שלא אוכל\" — \"שבועה דלא אכילנא\u0004 \u0005[שאינני אוכל]\u0006 \u0003\" קאמר\u0004 \u0005[אמר]\u0006 ולא כלשון תמיהה אלא כלשון שבועה ממש. ואם כן, אין לומר שאנו למדים מן ההקשר, לפי שאין לעמוד על משמעות הדברים באופן זה. \u0003אלא\u0004 ה\u0003תנא פסקה\u0004 \u0005[פסק]\u0006 וקבע כלל: \u0003\"שאוכל\" — \"דאכילנא\u0004 \u0005[שאוכל אני]\u0006 \u0003\"\u0004\u0003משמע, ו\"שלא אוכל\" — \"לא אוכל\" משמע,\u0004 ולכן יש לגרוס במשנתנו שאכן פירש ואמר \"שאי אוכל\".","\u0003זה חומר בשבועות מבנדרים\u0004 כפי שאמרנו במשנה הקודמת, שהשבועות חלות גם על דברים שאין בהם ממש, אלא על פעולות או על הימנעות מפעולה. \u0003וחומר\u0004 אחר יש \u0003בנדרים מבשבועות, כיצד? אמר \"קונם סוכה שאני עושה\",\u0004 או \u0003\"לולב שאני נוטל\",\u0004 או \u0003\"תפילין שאני מניח\",\u0004 אם אמר זאת \u0003בנדרים —\u0004 הרי הוא \u0003אסור\u0004 שחל האיסור על החפץ עצמו, ויצטרך התרה לנדרו כדי להשתמש בו ואף למצוה. ואילו \u0003בשבועות\u0004 כעין זה הוא \u0003מותר, שאין נשבעין לעבור על המצות\u0004 ואינו יכול לבטל על ידי שבועה את החובה שחלה עליו."],["שנינו במשנה: \"זה \u0003חומר\u0004 בשבועות מבנדרים\", ולפי משמעות הדברים הפשוטה מתייחס הדבר להבדל המפורש במשניות הקודמות בין האומר \"קרבן לא אוכל לך\", לאומר \"שבועה לא אוכל לך\". ותוהים: האם \u0003מכלל\u0004 הדברים אתה למד שגם אם אמר \"קרבן לא אוכל לך\" \u0003נדר הוא\u0004 על כל פנים מדברי סופרים, אלא שהשבועה חמורה ממנו לענין זה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"מותר\" קתני\u0004 \u0005[שנה]!\u0006 שבמשנה הקודמת שנינו שאם אומר \"קרבן לא אוכל לך\" — מותר, ואין מקום לומר שיש חומרה בשבועות מבנדרים — שהרי הנדר אינו נדר כלל!","ומסבירים: אלא \u0003אסיפא דאידך בבא קתני\u0004 \u0005[על סופה של הפיסקה\u0006 המשנה \u0005האחרת שנה]\u0006 דברים אלה, ששנינו שם שאם אמר \u0003\"שבועה שאיני ישן\" \"שאיני מדבר\" \"שאיני מהלך\" — אסור,\u0004 ועל כך אמר \u0003זה חומר בשבועות מבנדרים,\u0004 שנדר כגון זה אינו אסור אלא מדברי סופרים, אבל אינו חל מן התורה, ובזה חמורות שבועות מנדרים.","שנינו גם \u0003חומר בנדרים מבשבועות כיצד —\u0004 שהנדרים חלים גם על המצוה, מה שאין כן בשבועות. \u0003רב כהנא מתני\u0004 \u0005[היה שונה]\u0006 כך: \u0003אמר רב גידל אמר רב, ורב טביומי מתני\u0004 \u0005[היה שונה]\u0006 בלשון אחרת: \u0003אמר רב גידל אמר שמואל,\u0004 אבל האימרה היתה אותה אימרה: \u0003מנין שאין נשבעין לעבור על המצות — תלמוד לומר: \"לא יחל דברו\"\u0004 (במדבר ל, ג). ומדיוק הלשון נלמד: \u0003דברו\u0004 שלו, שאסר על עצמו — \u0003לא יחל, אבל מיחל הוא לחפצי שמים,\u0004 שאם נשבע שלא לעשות חפצי שמים — אין השבועה חלה.","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003נדר\u0004 שחל גם על דברי מצוה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"איש כי ידר נדר לה'... לא יחל דברו\"\u0004 (במדבר ל, ג) והיא לשון כללית, שאפילו היה זה בנושא השייך \"לה'\" — חפצי מצוה, בכל זאת לא יחל דברו, ונדרו חל גם על המצוה. אולם \u0003שבועה נמי\u0004 \u0005[גם כן],\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 באותו פסוק \u0003\"או השבע שבעה לה' לא יחל דברו\"!\u0004","\u0003אמר אביי:\u0004 יש להסביר שההבדל אינו בעצם הנדר או השבועה, אלא בדיוק הנוסח של הדבר שאסר על עצמו. כיצד? \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמר \"הנאת סוכה\u0004 אסורה \u0003עלי\",\u0004 שאסר על עצמו את ההנאה מן החפץ, ומשום כך חל הנדר עליו בכל מקרה, ואף במצוה, משום שאין מאכילים לאדם דבר האסור לו. \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמר \"שבועה שלא אהנה מן הסוכה\"\u0004 שאינו רשאי להישבע להימנע ממעשה שהוא חייב בו.","\u0003אמר רבא:\u0004 אי אפשר להסביר בדרך זו, \u0003וכי מצות ליהנות ניתנו?\u0004 ואיך יכול לאסור על עצמו הנאה מהמצוה? הלא אין אנו מחשיבים עשיית המצוות כשלעצמה כהנאה! \u0003אלא\u0004 יש לומר הסבר אחר, וכך \u0003אמר רבא: הא\u0004 \u0005[זה]\u0006 ש\u0003אמר \"ישיבת סוכה\u0004 אסורה \u0003עלי\",\u0004 שדבריו מועילים, \u0003והא\u0004 \u0005[וזה]\u0006 ש\u0003אמר \"שבועה שלא אשב בסוכה\",\u0004 שאין בדברי כלום.","ושואלים על עצם הלימוד שאין נשבעים לעבור על המצוות: \u0003ו\u0004הלכה זו \u0003שאין נשבעין לעבור על המצות מהכא נפקא ליה\u0004 \u0005[מכאן יוצאת,\u0006 נלמדת \u0005לו]\u0006 ההוכחה? הלא \u0003מהתם נפקא ליה\u0004 \u0005[משם,\u0006 מכתוב אחר, היא \u0005יוצאת,\u0006 נלמדת \u0005לו],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול\u0004 אם \u0003נשבע\u0004 אדם \u0003לבטל את המצוה ולא ביטל, יכול יהא חייב\u0004 משום שבועת שוא —"],["\u0003תלמוד לומר: \"\u0004או נפש כי תשבע לבטא בשפתים \u0003להרע או להיטיב\"\u0004 (ויקרא ה, ד), ומהשוואת \"להרע או להיטיב\" נלמד: \u0003מה הטבה\u0004 שנאמרה בכתוב שנשבע להיטיב כגון לאכול או להיטיב לאדם אחר היא \u0003רשות, אף הרעה\u0004 שהוא נשבע עליה — היא דווקא בדבר של \u0003רשות,\u0004 כגון שלא יאכל, וכדומה. \u0003יצא\u0004 ה\u0003נשבע לבטל את המצוה ולא ביטל —\u0004 שאינו מתחייב משום שבועת ביטוי — משום \u0003שאין הרשות בידו\u0004 לבטלה!","ומשיבים: שני המקראות נצרכים, \u0003חד קרא\u0004 \u0005[פסוק אחד]\u0006 \"להרע או להיטיב\" האמור בדיני הקרבנות הוא \u0003למיפטריה\u0004 \u0005[לפטור אותו]\u0006 \u0003מקרבן שבועה, וחד למיפטריה\u0004 \u0005[ו\u0006פסוק \u0005אחד לפטור אותו]\u0006 \u0003מן\u0004 איסור ה\u0003לאו\u0004 של \u0003שבועה,\u0004 והוא הכתוב בענין \"לא יחל דברו\".","\u0003יש נדר בתוך נדר,\u0004 שיכול להחיל איסור נוסף ונדר נוסף על דבר שכבר החיל עליו נדר. \u0003ואין שבועה בתוך שבועה,\u0004 שאם חוזר ונשבע על אותו דבר עצמו אין השבועה השניה חלה. ומפרטים, \u0003כיצד? אמר \"הריני נזיר אם אוכל\"\u0004 וחזר ואמר \u0003\"הריני נזיר אם אוכל\", ואכל — חייב\u0004 בנזירות שלושים יום \u0003על כל אחת ואחת\u0004 מן הפעמים שנדר, שחלו עליו שני הנדרים. אבל אם אמר \u0003\"שבועה שלא אוכל\"\u0004 וחזר ואמר \u0003\"שבועה שלא אוכל\" ואכל — אינו חייב\u0004 קרבן שבועה \u0003אלא\u0004 משום חילול שבועה \u0003אחת.\u0004","\u0003אמר רב הונא: לא שנו\u0004 שיש נדר בתוך נדר, \u0003אלא\u0004 ש\u0003אמר\u0004 תחילה \u0003\"הריני נזיר היום\"\u0004 ואחר כך אמר \u0003\"הריני נזיר למחר\"\u0004 ומדוע? \u0003דמיגו דקא מיתוסף יומא יתירא\u0004 \u0005[שמתוך שנוסף יום יתר]\u0006 של נזירות על ידי הנדר השני \u0003חיילא\u0004 \u0005[חלה]\u0006 \u0003נזירות\u0004 של שלושים יום נוספים \u0003על נזירות\u0004 הראשונה. \u0003אבל אמר \"הריני נזיר היום\"\u0004 וחזר ואמר \u0003\"הריני נזיר היום\" — אין חלה נזירות על נזירות,\u0004 ואין כאן אלא נזירות אחת. \u0003ושמואל אמר: אפילו אמר \"הריני נזיר היום, הריני נזיר היום\" חלה\u0004 ה\u0003נזירות\u0004 השניה \u0003עליה\u0004 \u0005[עליו],\u0006 כי ניתן להוסיף נדר נזירות נוסף גם על נזירות שנדר כבר.","ושואלים: \u0003ול\u0004דעת \u0003רב הונא, אדתנא\u0004 \u0005[עד\u0006 שהוא \u0005שונה]\u0006 במשנה \u0003אין שבועה בתוך שבועה\u0004 ומבדיל בין נדר לשבועה, \u0003ליתני\u0004 \u0005[שישנה]\u0006 התנא במשנה ויעשה חלוקה קרובה יותר בתוך דין הנדר עצמו, ויפרש: \u0003יש נדר בתוך נדר, ואין נדר בתוך נדר,\u0004 כיצד? אם אמר \u0003\"הריני נזיר היום, הריני נזיר למחר\" —\u0004 זהו המקרה ש\u0003יש נדר בתוך נדר,\u0004 אבל אם אמר \u0003\"הריני נזיר היום\"\u0004 וחזר ואמר \"\u0003הריני נזיר היום\"\u0004 —"],["\u0003אין נדר בתוך נדר!\u0004 ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר, אף שאין בכך פירכה גמורה. ומעתה מנסים להביא ראיות שונות נגד דברי רב הונא.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003יש נדר בתוך נדר ואין שבועה בתוך שבועה.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]\u0006 היה הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהוא במקרה ש\u0003אמר \"הריני נזיר היום, הריני נזיר למחר\" דכוותה\u0004 \u0005[שכיוצא בה]\u0006 \u0003גבי שבועה,\u0004 כגון שאמר \"שבועה \u0003שלא אוכל תאנים\" וחזר ואמר \"שבועה שלא אוכל ענבים\",\u0004 שנשבע שתי שבועות שונות — אולם במקרה כזה \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא חלה שבועה על שבועה?\u0004 בודאי שתחול, שהרי השבועה השניה אין לה קשר לראשונה!","\u0003אלא היכי דמי\u0004 \u0005[כיצד\u0006 הוא \u0005בדיוק]\u0006 ש\u0003לא חלה שבועה על שבועה — כגון\u0004 ש\u0003אמר \"שבועה שלא אוכל תאנים\" וחזר ואמר \"שבועה שלא אוכל תאנים\"\u0004 ובמקרה כזה אין השבועה השניה חלה כשבועה לעצמה, \u0003דכוותה\u0004 \u0005[שכיוצא בה]\u0006 ל\u0003גבי נזירות היכי דמי\u0004 \u0005[כיצד\u0006 הוא \u0005בדיוק]\u0006 — ש\u0003אמר \"הריני נזיר היום, הריני נזיר היום\" וקתני\u0004 \u0005[ושנה]\u0006 ש\u0003יש נדר בתוך נדר.\u0004 ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003לרב הונא,\u0004 שאמר שבמקרה כזה אין נדר חל על נדר!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב הונא: מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת במקרה ש\u0003אמר \"הריני נזיר היום, הריני נזיר למחר\", דכוותה\u0004 \u0005[שכיוצא בה]\u0006 ל\u0003גבי שבועה\u0004 צריך לומר שהיתה השבועה השניה כוללת את הראשונה ומוסיפה עליה, ש\u0003אמר \"שלא אוכל תאנים\" וחזר ואמר \"שבועה שלא אוכל תאנים וענבים\",\u0004 ש\u0003לא חיילא\u0004 \u0005[חלה]\u0006 השבועה השניה, שהרי על חלק ממנה כבר היה מושבע ועומד.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה:\u0004 האומר \u0003\"שבועה שלא אוכל תאנים\" וחזר ואמר \"שבועה שלא אוכל תאנים וענבים\"\u0004 ועבר \u0003ואכל תאנים, והפריש קרבן\u0004 מפני שעבר על שבועת ביטוי, \u0003וחזר ואכל ענבים —\u0004 במקרה זה \u0003הויא להו\u0004 \u0005[הרי הם]\u0006 ה\u0003ענבים\u0004 שאכל רק \u0003חצי שיעור\u0004 משבועתו השניה, שהרי כלל בשבועתו תאנים וענבים, משמע שכוונתו שאוסר על עצמו אכילת שניהם יחד. וכיון שהפריש כבר קרבן על התאנים, נחשב כאילו אכל ענבים בלבד ועבר רק על חלק מן השבועה, ונמצא שהוא כחצי שיעור, \u0003ואין מביאים קרבן על חצי שיעור.\u0004","\u0003אלמא\u0004 \u0005[מכאן]\u0006 אם נדקדק בדבריו נמצא כי \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003אמר \"שבועה שלא אוכל תאנים\" וחזר ואמר \"שבועה שלא אוכל תאנים וענבים\"\u0004 ולא הפריש קרבן בינתיים, \u0003מיגו\u0004 \u0005[מתוך]\u0006 ש\u0003חל\u0004 כוח ה\u0003שבועה על ענבים\u0004 שהוסיף בשבועתו — \u0003חיילא נמי\u0004 \u0005[חלה גם כן]\u0006 \u0003על תאנים,\u0004 שהרי לא נפטר מקרבן אלא משום שהיה זה חצי שיעור, ובניגוד לדברי הונא! ומתרצים: זו אינה קושיה, שהרי רבה היה אמורא (וכתלמיד לרב הונא) ואילו \u0003רב הונא לא סבירא ליה\u0004 \u0005[אינו סבור]\u0006 \u0003כרבה\u0004 בענין זה, ולדעתו השבועה השניה לא חלה כלל.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003מי שנזר שתי נזירות, מנה את\u0004 ימי הנזירות \u0003הראשונה והפריש קרבן\u0004 בסוף שלושים ימי הנזירות, \u0003ונשאל עליה,\u0004 שלפני שהקריב את הקרבן הזה הלך לחכם, והחכם התיר לו את נדר הנזירות הראשון, ונמצא שלא היתה כאן נזירות כלל, אבל כיון שנדר שני נדרי נזירות, היה עליו גם נדר נזירות אחר, ואז \u0003עלתה\u0004 (נחשבה) \u0003לו\u0004 נזירות \u0003שניה בראשונה,\u0004 שנחשב לו כאילו קיים את הנזירות השניה באותו זמן שבפועל נהג נזירות הראשונה, והקרבן שהפריש נחשב לו בשביל הנזירות השניה.","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003אמר \"הריני נזיר היום, הריני נזיר למחר\" —\u0004 במקרה זה \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003עלתה לו שניה בראשונה? הא איכא יומא יתירא\u0004 \u0005[הרי יש יום יתר]\u0006 של הנזירות השניה שעדיין לא קיים אותו, וכיצד אפשר לומר שכבר יצא ידי חובתו בראשונה? \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר פה ש\u0003אמר \"הריני נזיר היום, הריני נזיר היום\"\u0004"],["\u0003ו\u0004הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב הונא!\u0004","ודוחים: \u0003לא, לעולם\u0004 תפרש נזירות חלה על נזירות, דווקא כשאמר \u0003\"הריני נזיר היום, הריני למחר\", ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"עלתה לו\u0004 שניה בראשונה \u0003\",\u0004 הכוונה — \u0003לבר מההוא יומא יתירא\u0004 \u0005[חוץ מאותו יום יתר],\u0006 שאותו צריך להשלים. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יכול אתה לפרש את הענין הזה שעלתה לו נזירות שניה \u0003כגון שקיבל\u0004 עליו \u0003שתי נזירות בבת אחת,\u0004 שאמר שיהיה פעמיים נזיר, ואם נשאל על הנזירות הראשונה והותר, חלה עליו השניה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב המנונא\u0004 קושיה נוספת על דברי רב הונא מברייתא: שנינו על הכתוב \u0003\"נזיר להזיר\"\u0004 (במדבר ו, ב) — \u0003מכאן שהנזירות חל על הנזירות.\u0004 ומדוע נחוץ כתוב מפורש לומר זאת — \u0003שיכול\u0004 הייתי לומר כך: \u0003והלא דין\u0004 (קל וחומר) \u0003הוא: ומה שבועה\u0004 שהיא \u0003חמורה —\u0004 בכל זאת \u0003אין שבועה חלה על שבועה, נזירות\u0004 שהיא \u0003קלה\u0004 ממנה \u0003לא כל שכן\u0004 שלא תחול על נזירות אחרת — \u0003תלמוד לומר:\u0004 מן הכפל שבכתוב \u0003\"נזיר להזיר\", מכאן שהנזירות חלה על הנזירות.\u0004","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 במקרה ש\u0003אמר \"הריני נזיר היום, הריני נזיר למחר\"\u0004 וכי \u0003הא קרא בעיא\u0004 \u0005[זו מקרא\u0006 היא \u0005צריכה]?!\u0006 הרי ברור שחלה הנזירות השניה לפחות ביום הנוסף, וכיון שאין נזירות פחות משלושים יום צריך למנות עוד שלושים יום! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר פה כגון ש\u0003אמר \"הריני נזיר היום, הריני נזיר היום\" וקתני\u0004 \u0005[ושנה]\u0006 ש\u0003נזירות חל על נזירות,\u0004 שלא כדברי רב הונא!","ודוחים: \u0003לא, הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שקיבל עליו שתי נזירות בבת אחת,\u0004 ולמדים מהפסוק שחייב בקרבנות על כל נזירות בפני עצמה.","לגופה של אותה ברייתא שואלים: \u0003ומאי חומרא\u0004 \u0005[ומהי החומרה]\u0006 שיש ב\u0003שבועה מנדר,\u0004 כגון נדר נזירות? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דחיילא\u0004 \u0005[שחלה]\u0006 השבועה \u0003אפילו על דבר שאין בו ממש,\u0004 יכול אתה לטעון כנגד זה ש\u0003נדר\u0004 יש בו \u0003נמי\u0004 \u0005[גם כן]\u0006 צד \u0003חמור\u0004 משבועה, \u0003שכן חל על המצוה כרשות. אלא\u0004 הטעם הוא אחר — \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה בשבועה: \"לא ינקה\u0004 ה' את אשר ישא את שמו לשוא\u0003\"\u0004(שמות כ, ז), ומחומרת העונש יש להבין ששבועה הריהי חמורה ביותר.","שנינו במשנה שאם אמר \u0003\"שבועה שלא אוכל, שבועה שלא אוכל\", ואכל — אינו חייב אלא אחת. אמר רבא: אם נשאל\u0004 לפני חכם \u0003על\u0004 השבועה \u0003הראשונה\u0004 והתירה לו — \u0003שניה חלה עליו. ממאי\u0004 \u0005[ממה]\u0006 יודע הוא שהשבועה השניה חלה — \u0003מדלא קתני\u0004 \u0005[מ\u0006פני \u0005שלא שנה]\u0006 במשנה בלשון \u0003\"אינו אלא אחת\",\u0004 לומר שהשבועה השניה זהה לגמרי לראשונה, וכאילו לא נשבע אלא פעם אחת, \u0003וקתני\u0004 \u0005[ושנה]\u0006 בלשון \u0003\"אינו חייב אלא אחת\",\u0004 מכאן אנחנו למדים שהסברה היא כי \u0003רווחא\u0004 \u0005[רווח,\u0006 אפשרות\u0005]\u0006 \u0003הוא דלית\u0004 \u0005[שאין]\u0006 \u0003לה\u0004 לשבועה השניה שתחול, שהרי כבר מושבע ועומד הוא על הדבר. אבל \u0003כי מיתשיל\u0004 \u0005[כאשר\u0006 הוא \u0005נשאל]\u0006 \u0003על חבירתה\u0004 השבועה הראשונה ומתפנה הדבר — \u0003חיילא\u0004 \u0005[חלה]\u0006 השבועה השניה.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 בדקדוק לשון המשנה להוכיח כדברי רבא, שכיון שנאמר במשנה \"אינו חייב אלא אחת\" יש להסיק מכאן ש\u0003חיובא\u0004 \u0005[חיוב]\u0006 \u0003הוא דליכא\u0004 \u0005[שאין]\u0006 בשבועה השניה, שאינו חייב עליה קרבן משום שבועת ביטוי, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שבועה\u0004 עצמה \u0003איכא\u0004 \u0005[יש]\u0006 עליו. ויש לשאול: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נאמר שיש כאן שבועה, אם אינו מתחייב דבר בגללה? אלא ודאי \u0003לכ\u0004 דברי \u0003רבא,\u0004 ש\u0003אמר רבא: נשאל על הראשונה\u0004 — \u0003עלתה לו שניה תחתיה.\u0004","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 ממה ששנינו: \u0003מי שנדר שתי נזירות ומנה את הראשונה, והפריש קרבן ונשאל עליה — עלתה לו שניה בראשונה.\u0004 משמע שנדר הנזירות השני, למרות שבשעת הנדר לא היה לו מקום לחול (שהרי כבר נדר לגבי אותו זמן), מכל מקום יש לו חלות מסויימת ואינו בטל לגמרי, וכאשר מתבטל הנדר הראשון — מיד חל עליו השני, ומכאן נוכיח גם לענין שבועה.","ודוחים: אפשר לפרש ששם מדובר \u0003כגון שקיבל עליו שתי נזירות בבת אחת\u0004 שהן חלות מתחילה בזו אחר זו, ולא בבת אחת. אבל כאשר היתה שבועה על שבועה, לגבי אותו מקום ואותו זמן — אין ראיה מכאן שהשבועה השניה חלה כלל."],["\u0003סתם נדרים להחמיר, ופירושם\u0004 אם מפרש אותם בצורה מסויימת יכול להיות \u0003להקל. כיצד? אמר \"הרי\u0004 דבר זה \u0003עלי כבשר מליח\"\u0004 או אמר \u0003\"כיין נסך\",\u0004 בכל אלה \u0003אם בשל שלמים נדר,\u0004 אם אומר שהתכוון לומר שבשר זה יהיה כבשר מליח (מלוח) של קרבן, או כיין שמנסכים על המזבח — הרי זה \u0003אסור,\u0004 שהרי התפיס את נדרו בדבר הנדור.","ו\u0003אם\u0004 אומר ש\u0003בשל עבודה זרה נדר\u0004 שיהא הבשר אסור עליו כבשר מלוח של קרבן עבודה זרה, או כיין נסך שמנסכים הגויים לעבודתם — במקרה זה \u0003מותר,\u0004 שהרי התפיס בדבר האסור. הרי שפירושו של נדר זה הוא במקרה זה להקל. \u0003ואם\u0004 אמר \u0003סתם\u0004 ולא פירש באיזה ענין נדר, אם של שמים או של עבודה זרה — הרי זה \u0003אסור.\u0004","וכן אם אמר \u0003\"הרי עלי\u0004 דבר זה \u0003כחרם\", אם\u0004 התכוון \u0003כחרם של שמים\u0004 שהוא ממיני הקדש — \u0003אסור, ואם\u0004 התכוון \u0003כחרם של כהנים\u0004 שמחרים אדם נכסיו כמתנה לכהנים — הרי זה \u0003מותר,\u0004 שזה סוג של מתנה, ואין בו גדר של נדר. \u0003ואם\u0004 אמר \u0003סתם — אסור.\u0004","וכן אם אמר \u0003\"הרי עלי כמעשר\", אם כמעשר בהמה נדר —\u0004 הרי זה \u0003אסור,\u0004 שהוא קרבן, ונדר בדבר הנדור. \u0003ואם\u0004 פירש שהתכוון למעשר \u0003של גורן,\u0004 מן התבואה, הניתן ללוויים ואין בו קדושה — \u0003מותר. ואם\u0004 אמר \u0003סתם — אסור.\u0004","וכן אם אמר \u0003\"הרי עלי כתרומה\", אם כתרומת הלשכה נדר,\u0004 שהיא התרומה שתורמים לצורך קרבנות הציבור — במקרה זה \u0003אסור,\u0004 שהרי התפיס בהקדש הנדור. \u0003ואם\u0004 התכוון לתרומה \u0003של גורן\u0004 שנותנים לכהנים — \u0003מותר,\u0004 שאינה דבר הנדור אלא מתנה לכהנים. \u0003ואם סתם — אסור.\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יהודה אומר: סתם תרומה, ביהודה — אסורה, בגליל — מותרת,\u0004 ומדוע? \u0003שאין אנשי גליל מכירין את תרומת הלשכה,\u0004 ולכן כשהם אומרים \"תרומה\" הם מתכוונים לתרומה המצויה אצלם, היא תרומת הכהנים. וכן \u0003סתם חרמים, ביהודה — מותרין, בגליל — אסורין,\u0004 ומדוע — \u0003שאין אנשי גליל מכירין את חרמי הכהנים,\u0004 וכשהם אומרים \"חרם\" סתם — כוונתם: חרם לשמים.","על הכלל שבמשנה ש\"סתם נדרים להחמיר\", שואלים: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003ספק נזירות להקל,\u0004 והנזירות הלא היא אחד ממיני הנדרים, ומדוע אמרו כאן שספק נדרים להחמיר ולא להקל?","\u0003אמר ר' זירא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו],\u0006 המשנה לגבי ספק נזירות, היא כשיטת \u0003ר' אליעזר, הא\u0004 \u0005[זו],\u0006 משנתנו, כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים עליו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המקדיש חייתו ובהמתו — הקדיש\u0004 עימם גם \u0003את הכוי\u0004 שהוא ספק חיה ספק בהמה. \u0003ר' אליעזר אומר: לא הקדיש את הכוי.\u0004","ומכאן נלמד לענייננו; \u0003מאן דאמר\u0004 \u0005[מי שאומר],\u0006 חכמים הסבורים שאדם את \u0003ממונו מעייל לספיקא\u0004 \u0005[מכניס לספק],\u0006 שגם את הכוי, אף שהוא ספק חיה ספק בהמה, מכניס אדם בתוך ההגדרה הכללית, סבור גם כן כי \u0003גופיה נמי מעייל\u0004 \u0005[את גופו,\u0006 עצמו, \u0005גם כן מכניס]\u0006 לספק. ולכן גם אם יש ספק בנזירות — הרי זה נדר. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר],\u0006 ר' אליעזר, כי את \u0003ממונו לא מעייל לספיקא\u0004 \u0005[אינו מכניס לספק]\u0006 וכשאמר חיה ובהמה התכוון לחיה ודאית ולבהמה ודאית ולא לספק, \u0003גופיה\u0004 \u0005[את עצמו]\u0006 \u0003(נמי\u0004 \u0005[גם כן]\u0006\u0003)\u0004"],["\u0003כל שכן\u0004 ש\u0003לא מעייל לספיקא\u0004 \u0005[מכניס לספק].\u0006 ולכן, בכל נוסח שיש בו ספק — מותר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לר' זעירא: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת]\u0006 את המשנה של \u0003ספק נזירות להקל — כר' אליעזר, אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003ספק בכורות, אחד בכורי אדם ואחד בכורי בהמה, בין\u0004 שהוא בכור בהמה \u0003טמאה\u0004 (פטר חמור) \u0003בין טהורה,\u0004 בכל המקרים הללו — \u0003המוציא מחבירו עליו הראיה,\u0004 שאין הכהן יכול להוציא מיד הבעלים. ולחילופין, אם טעו הבעלים ונתנו לכהן — אין הבעלים יכולים לחזור ולהוציא מידו.","\u0003ותני עלה\u0004 \u0005[ושנויה עליה]\u0006 על משנה זו, ברייתא: \u0003ו\u0004בכל זאת, כל הספיקות הללו \u0003אסורים בגיזה ועבודה\u0004 בהם, כדינו של בכור. משמע שהאיסור חל אפילו במקום ספק, אף שמבחינת דיני ממונות אי אפשר להוציא ממון זה מן הבעלים. ואם כן, אף משנה זו אינה סבורה שכל ספק בעניינים של הקדשה הוא להקל!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 זו אינה קושיה; \u0003אמאי קא מדמית\u0004 \u0005[מדוע אתה מדמה]\u0006 \u0003קדושה הבאה מאליה\u0004 כקדושת בכור, שאינה תלויה ברצונו ובכוונתו של האדם, והספק קיים מצד המציאות, \u0003לקדושה הבאה בידי אדם,\u0004 שהיא תלויה ברצונו, שאפשר לומר אז שאין אדם רוצה להקדיש דבר מספק?","\u0003אלא אי קשיא, הא קשיא\u0004 \u0005[אם קשה, זה\u0006 הוא הדבר \u0005הקשה],\u0006 ששנינו עוד באותה משנה: \u0003ספק משקין,\u0004 שלא ברור לנו אם נטמאו במגע אדם טמא, אם לענין \u0003ליטמא\u0004 המשקים עצמם — אנו מחשיבים אותם \u0003טמא\u0004 אבל לענין \u0003לטמא אחרים —\u0004 הרי זה \u0003טהור,\u0004 אלו \u0003דברי ר' מאיר, וכן היה ר' אלעזר אומר כדבריו.\u0004","ואם אנו מעמידים משנה זו בספק נזיר ושאר ספיקות כדברי ר' אליעזר, יש לשאול: \u0003ומי סבירא ליה\u0004 \u0005[והאם סבור]\u0006 \u0003לר' אליעזר\u0004 שספק משקים \u0003ליטמא\u0004 דינו \u0003טמא?\u0004","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: אין טומאה למשקין כל עיקר\u0004 מדין תורה. \u0003תדע\u0004 שכן הוא: \u0003שהרי העיד יוסי בן יועזר איש צרידה על\u0004 מין חגב אחד שנקרא \u0003איל קמצא\u0004 שהוא \u0003דכן\u0004 \u0005[טהור]\u0006 וכשר לאכילה, \u0003ועל משקין בית מטבחיא דכן\u0004 \u0005[\u0006של \u0005בית המטבחיים\u0006 של המקדש, שהם \u0005טהורים].\u0006 כי טומאת המשקים אינה אלא מדברי חכמים, ולא גזרו חכמים טומאה על משקים שבמקדש, כדי שלא להרבות שם בטומאה. ומדבריו של ר' אליעזר ברור שהוא סבור שטומאת משקים אינה מן התורה, וכיצד אפשר לייחס לו את המשנה האומרת שספק משקים טמא?","\u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003שמואל\u0004 ש\u0003אמר\u0004 שמה שאמרו \u0003דכן\u0004 \u0005[טהורים]\u0006 כוונתו שהם טהורים \u0003מלטמא אחרים,\u0004 שרק דין זה שמשקים מטמאים את הנוגע בהם הוא מדברי סופרים, \u0003אבל טומאת עצמן\u0004 להיטמא \u0003יש בהן\u0004 מן התורה. ולשיטה זו \u0003שפיר\u0004 \u0005[יפה],\u0006 שאפשר לומר שגם ר' אליעזר מודה שטומאה חלה על המשקים להיטמא מדברי תורה, ולכן ספיקם טמא.","\u0003אלא ל\u0004דעת \u0003רב\u0004 ש\u0003אמר\u0004 כי הם \u0003דכן\u0004 \u0005[טהורים]\u0006 \u0003ממש,\u0004 שאין בהם טומאה כל עיקר אפילו להיטמא, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שלפי זה ברור שהמשנה המקילה בספק נזירות והאומרת שספק משקים להיטמא טמא אינה כשיטת ר' אליעזר!","\u0003אלא\u0004 יש לחזור מתירוץ זה, ואת הסתירה בין מה שנאמר במשנתנו שסתם נדרים להחמיר, ובין מה שאמרו במשנת טהרות שספק נזירות להקל, יש ליישב כך: \u0003הא\u0004 \u0005[זו]\u0006 המשנה בטהרות, האומרת שספק נזירות להקל, היא כשיטת \u0003ר' יהודה, והא\u0004 \u0005[וזו]\u0006 משנתנו, האומרת שספק נדרים להחמיר היא כשיטת \u0003ר' שמעון.\u0004 ומהי מחלוקתם?","— \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אמר אדם \u0003\"הריני נזיר אם יש בכרי\u0004 (ערימת תבואה) \u0003הזה מאה כור\u0004 (מידת נפח) \u0003\", והלך\u0004 לכרי לבדוק \u0003ומצאו שנגנב\u0004 הכרי \u0003או שאבד,\u0004 ואי אפשר לברר מיד את הדבר. \u0003ר' יהודה מתיר,\u0004 וסבור שלא חלה עליו נזירות מספק. \u0003ור' שמעון אוסר\u0004 מחמת הספק. משמע שר' שמעון סבור שאף נדר נזירות ספיקו לחומרה.","ומעירים: \u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה\u0004 עצמם. כיצד? \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יהודה\u0004 כי \u0003לא מעייל איניש נפשיה לספיקא\u0004 \u0005[אין אדם מכניס\u0006 את \u0005עצמו לספק]\u0006 ומשום כך לענין הכרי כל עוד לא נתברר מה היה גודל הכרי לא חלה עליו נזירות? \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו, \u0003ר' יהודה אומר: סתם תרומה ביהודה — אסורה, ובגליל — מותרת, שאין אנשי הגליל מכירין את תרומת הלשכה.\u0004 ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003אין מכירין,\u0004"],["\u0003הא\u0004 \u0005[הרי]\u0006 אם היו \u0003מכירין — אסורין\u0004 אף על פי שאמר תרומה סתם, ועדיין הדבר בגדר ספק לאיזו תרומה התכוון!","\u0003אמר רבא\u0004 אפשר לתרץ כך: \u0003גבי\u0004 \u0005[אצל]\u0006 הענין של \u0003כרי\u0004 שעשה עליו תנאי \"הריני נזיר אם יש בו מאה כור\", \u0003קסבר\u0004 \u0005[סבור]\u0006 ר' יהודה ש\u0003כל\u0004 דבר \u0003שספיקו חמור מודאי — לא מעייל נפשיה לספיקא\u0004 \u0005[אין\u0006 אדם \u0005מכניס\u0006 את \u0005עצמו לספק\u0006 כזה\u0005],\u0006 ובמה ספיקו חמור מוודאו — ש\u0003אילו גבי\u0004 \u0005[אצל]\u0006 \u0003נזיר ודאי\u0004 יש לו דרך של תיקון, שבסיום נזירותו \u0003מגלח\u0004 את ראשו \u0003ומביא קרבן, ונאכל.\u0004 אבל \u0003על ספיקו,\u0004 על נזירות מחמת הספק, \u0003לא מצי מגלח\u0004 \u0005[אינו יכול לגלח].\u0006 שאינו יכול להביא קרבן — שמא אינו נזיר והרי הוא מכניס חולין לעזרה, וכיון שאינו מביא קרבן — אינו יכול לגלח.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בר יהודה לרבא:\u0004 אם הנימוק הוא מפני שספיקו חמור מוודאו, אם \u0003אמר\u0004 אדם: \u0003\"\u0004אם יש בכרי הזה מאה כור \u0003הריני נזיר עולם\", מאי\u0004 \u0005[מה]\u0006 דינו? הרי לכאורה אין במקרה זה הבדל בין ספיקו לוודאו, שאף בוודאו אינו יוצא לעולם מגדר נזירות!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נזיר עולם נמי\u0004 \u0005[גם כן]\u0006 \u0003ספיקו חמור מודאי,\u0004 ש\u0003אילו ודאי\u0004 נזיר עולם הלכה היא שאם \u0003הכביד\u0004 עליו \u0003שערו\u0004 יותר מדי — \u0003מיקל\u0004 מן השיער \u0003בתער, ומביא שלוש בהמות\u0004 לקרבן כדין נזיר שסיים נזירותו, וממשיך לנהוג נזירות. \u0003ואילו\u0004 במקום של \u0003ספיקו — לא,\u0004 כיון שאין ודאות שהוא נזיר אינו יכול להביא קרבנות אלה ואסור בגילוח לעולם, ונמצא שספיקו חמור מוודאו.","ועוד שאל אותו: ואם \u0003אמר \"הריני נזיר שמשון\u0004 אם יש בכרי הזה מאה כור \u0003\",\u0004 כלומר, נזיר כמו שמשון שאין לו התרה לעולם ואין לו תיקון כלל על ידי קרבנות, ואינו מגלח כל ימיו, \u0003מאי\u0004 \u0005[מה]\u0006 יהיה דינו, שהרי כאן אין הבדל בין ספק לוודאי?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נזיר שמשון לא תניא\u0004 \u0005[איננה שנויה],\u0006 כלומר, הענין הזה של נזירות שמשון אינו נזכר כלל בדברי חכמים, מפני שלא היתה זו נזירות ממש, אלא הוראה מיוחדת משמים לשמשון, ואין אדם יכול לידור נדר נזירות כזו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב אדא בר אהבה: תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 העוסקת במי שנדר להיות \u0003נזיר שמשון! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי תניא\u0004 \u0005[אם שנויה]\u0006 — \u0003תניא\u0004 \u0005[שנויה],\u0006 ואין אני יכול להתנגד לדברי הברייתא, ולשיטתו יודה ר' יהודה במקרה זה שחלה עליו נזירות אפילו על הספק.","\u0003רב אשי אמר:\u0004 אפשר לתרץ את הסתירה בדברי ר' יהודה באופן אחר, כי \u0003ההיא\u0004 \u0005[אותה]\u0006 ברייתא שאמר ר' יהודה שאם אי אפשר לברר מה גודל הכרי אין זו נזירות — זו דעת \u0003ר' יהודה משום\u0004 (בשם) \u0003ר' טרפון היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם היו אנשים אחדים אומרים בדרך של התערבות שאם יימצא הדבר כדברי אחד מהם — יהיה נזיר, \u0003ר' יהודה משום ר' טרפון אומר: אין אחד מהם נזיר,\u0004 בין זה שזכה בהתערבות ובין זה שהפסיד בה, וטעמו — \u0003לפי שלא ניתנה נזירות אלא להפלאה,\u0004 שאין נדר נזירות חל אלא במקום שיש בו ודאות ובהירות בשעה שנדר, שאדם מקבל את נדר הנזירות על עצמו בלא תנאי. ולפי זה, במקרה כגון הכרי, שלא היה הדבר ברור לנודר מה שיעור הכרי — לא חלה עליו נזירות.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש לפי שיטה זו \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 שיחלקו במקום \u0003שנגנב או שאבד\u0004 הכרי? אפילו לא נגנב גם כן לא תחול הנזירות, שהרי לא היתה כאן הפלאה! ומשיבים: \u0003אלא,\u0004 יש להסביר כי נשנתה המחלוקת במקרה של נגנב ואבד \u0003להודיעך כחו\u0004 של \u0003ר' שמעון, דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003נגנב או שאבד\u0004 ולא ברור מה היה שיעורו, בכל זאת \u0003קסבר\u0004 \u0005[סבור]\u0006 הוא כי \u0003מעייל איניש נפשיה לספיקא\u0004 \u0005[מכניס אדם\u0006 את \u0005עצמו לספק]\u0006 וחל עליו הנדר.","שנינו במשנה ש\u0003ר' יהודה אומר:\u0004 האומר \u0003סתם תרומה, ביהודה —\u0004 אסור, בגליל — מותר, מפני שאין אנשי גליל מכירים את תרומת הלשכה. ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היו \u0003מכירין\u0004 את תרומת הלשכה — היו \u0003אסורין, אלמא\u0004 \u0005[מכאן]\u0006 אנו יכולים להסיק ש\u0003ספיקא\u0004 \u0005[ספק]\u0006 נדרים הולכים בו \u0003לחומרא\u0004 \u0005[להחמיר].\u0006","אולם, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003סתם חרמים ביהודה — מותרין, ובגליל — אסורין, שאין אנשי הגליל מכירין את חרמי הכהנים,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היו \u0003מכירין\u0004 את חרמי הכהנים — משמע שהיו \u0003מותרין,\u0004 מפני שיש בכך ספק. \u0003אלמא\u0004 \u0005[מכאן]\u0006 שלגבי נדרים \u0003ספיקא לקולא\u0004 \u0005[הספק\u0006 הוא \u0005להקל]!\u0006","\u0003אמר אביי: סיפא\u0004 \u0005[סופה]\u0006 של המשנה שיטת \u0003ר' אלעזר בר' צדוק היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: סתם תרומה ביהודה — אסורה, ר' אלעזר בר' צדוק אומר: סתם חרמים, בגליל — אסורין.\u0004 ושיטה זו שסתם חרמים בגליל אסורים היא שיטת ר' אלעזר בר' צדוק, ולא שיטת ר' יהודה."],["\u0003נדר בחרם,\u0004 כגון שאמר \"הרי עלי חפץ זה בחרם\", \u0003ואמר\u0004 והסביר אחר כך את דבריו: \u0003לא נדרתי,\u0004 כלומר, לא התכוונתי בליבי, \u0003אלא בחרמו של ים,\u0004 שהתכוונתי ל\"חרם\" במשמעות רשת דייגים. נדר \u0003בקרבן ואמר\u0004 אחר כך: \u0003לא נדרתי אלא בקרבנות של מלכים,\u0004 כלומר, במה שמביאים כמתנה כתקרובת למלך, ולא בקרבן לה'.","או אמר \u0003\"הרי עצמי קרבן\" ואמר\u0004 והסביר: \u0003לא נדרתי אלא בעצם שהנחתי לי להיות נודר בו,\u0004 ו\"עצמי\" משמעו — עצם שלי, הנחתיה כדי שאוכל להראות כאילו אני נודר בעצמי. או אמר \u0003\"קונם אשתי נהנית לי\" ואמר\u0004 והסביר: \u0003לא נדרתי אלא באשתי הראשונה שגירשתי,\u0004 ולא על זו שאני נשוי לה כעת —","\u0003על כולן אין נשאלין להם,\u0004 כלומר, אין צריכים להתיר אותם, שהרי אותם שנדרו אומרים בפירוש שלא היתה כוונתם לשם נדר. \u0003ואם נשאלו,\u0004 שהנודר אינו בטוח בדבר ובא להישאל על הנדר — \u0003עונשין אותן ומחמירין עליהן\u0004 ואין מתירים להם. אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים:\u0004 אין מחמירים עליהם, אלא \u0003פותחין להן פתח\u0004 להתיר את הנדר \u0003ממקום אחר,\u0004 לא מגופו של נדר, \u0003ומלמדין אותן\u0004 שלא יעשו כן עוד להבא. ומדוע עושים כן? — \u0003כדי שלא ינהגו קלות ראש בנדרים.\u0004","על ההלכה לגבי נדרים אלה מעירים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה]:\u0006 \u0003אמרת\u0004 מצד אחד: \u0003אין נשאלין להן,\u0004 שאינם צריכים התרה, \u0003והדר תני\u0004 \u0005[וחזר ושנה]:\u0006 \u0003אם נשאלו עונשין אותן ומחמירין עליהן,\u0004 הרי שיש צורך להתיר נדרים אלו, ואם כן כיצד יש לפרש סתירה זו?","\u0003אמר רב יהודה: הכי קתני\u0004 \u0005[כך שנה],\u0006 כך יש להבין: \u0003וכולן אין צריכין שאלה\u0004 מעיקר הדין, \u0003במה דברים אמורים — בתלמיד חכם\u0004 שיודע שבמקרה זה אינו נדר, ומתחילה לא נדר, \u0003אבל בעם הארץ שבא לישאל — עונשין אותו ומחמירין עליו.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שאמרנו \u0003מחמירין —\u0004 כוונתו \u0003דלא פתחינן ליה\u0004 \u0005[שאין אנו פותחים לו]\u0006 פתח להתיר את הנדר על ידי \u0003חרטה\u0004 בלבד, אבל מנסים למצוא דרך אחרת להתיר לו את הנדר. \u0003אלא עונשין היכי דמי\u0004 \u0005[כיצד\u0006 הוא \u0005בדיוק]?\u0006","ומסבירים: \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מי שנזר ועבר על נזירותו — אין נזקקין לו\u0004 להתיר לו את נדר הנזירות בחרטה \u0003עד שינהוג בו\u0004 (בעצמו) \u0003איסור\u0004 של נזירות \u0003כימים שנהג בהן היתר,\u0004 שלא נהג בנזירות. אלו \u0003דברי ר' יהודה. אמר ר' יוסי: במה דברים אמורים\u0004 שנוהג איסור כמשך אותם ימים שנדר — שנזר \u0003בנזירות מועטת\u0004 שאינה עולה על שלושים יום. אבל \u0003בנזירות מרובה — דיו\u0004 שיהא נזיר \u0003שלשים יום\u0004 ואף אם עבר על נזירותו מספר רב יותר של ימים. והוא הענין שעונשים עם הארץ שבא להישאל על נדרים אלו שבמשנה — שבמשך זמן מסויים צריך לקיים את הנדר.","\u0003אמר רב יוסף: הואיל ואמרי רבנן\u0004 \u0005[ואמרו חכמים]\u0006 \u0003אין נזקקים לו,\u0004 משום כך \u0003בי דינא דמזדקקי\u0004 \u0005[בית דין שנזקק]\u0006 לו להתיר את הנדר הזה מיד \u0003לא עביד שפיר\u0004 \u0005[אינו עושה יפה].\u0006 \u0003רב אחא בר יעקב אומר:\u0004 אף \u0003משמתינן ליה\u0004 \u0005[מנדים אותו]\u0006 את החכם שהתיר מיד.","שנינו במשנה, \u0003\"וחכמים אומרים: פותחין לו פתח\u0004 ממקום אחר ומלמדים אותו שלא יקל ראש בנדרים \u0003\". תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003לעולם אל תהי רגיל בנדרים,\u0004 והטעם — \u0003שסופך\u0004 אם תהא רגיל בהם ומזלזל בהם להגיע \u0003למעול\u0004 אף \u0003בשבועות\u0004 החמורות יותר. \u0003ואל תהי רגיל אצל עם הארץ,\u0004 כיון \u0003שסופך\u0004 שיבוא אותו עם הארץ \u0003להאכילך טבלים,\u0004 שהוא אינו מדקדק בהפרשת מעשרות, ולבסוף יזדמן לך שתאכל טבל אצלו. וכן \u0003אל תהי רגיל אצל כהן עם הארץ,\u0004 כיון \u0003שסופך\u0004 שיבוא \u0003להאכילך תרומה.\u0004 שמחמת קירבה עלול להאכיל אותך תרומה, שהיא אסורה לישראל באיסור מיתה. \u0003ואל תרבה שיחה עם האשה — שסופך לבוא\u0004 מתוך כך \u0003לידי ניאוף.\u0004","\u0003ר' אחא בר' יאשיה אומר: כל הצופה\u0004 (המסתכל) \u0003בנשים — סופו בא לידי עבירה\u0004 בפועל. \u0003וכל המסתכל בעקבה של אשה, הויין לו\u0004 \u0005[יהיו לו]\u0006 כעונש על כך \u0003בנים שאינן מהוגנין. אמר רב יוסף:\u0004 איסור זה הוא בכל אשה, \u0003ו\u0004גם \u0003באשתו\u0004 כשהיא \u0003נדה. אמר ר' שמעון בן לקיש: עקבה דקתני\u0004 \u0005[ששנה]\u0006 שם איננו עקב הרגל, אלא הכוונה היא \u0003במקום הטנופת\u0004 (מקום הערווה) וקראו לו בלשון נקיה \"עקב\", משום \u0003שהוא מכוון כנגד העקב.\u0004","בדומה לזה \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"\u0004ו\u0003בעבור תהיה יראתו על פניכם\"\u0004 (שמות כ, יז), וכוונתו — \u0003זו בושה,\u0004 שהיא יראת שמים הנראית על פניו של אדם. \u0003\"לבלתי תחטאו\"\u0004 (שמות כ, יז) — \u0003מלמד שהבושה מביאה לידי יראת חטא. מיכן\u0004 (מכאן) \u0003אמרו: סימן יפה באדם שהוא ביישן. אחרים אומרים: כל אדם המתבייש, לא במהרה הוא חוטא.\u0004 ולהיפך, \u0003ומי שאין לו בושת פנים — בידוע שלא עמדו אבותיו על הר סיני.\u0004","\u0003אמר ר' יוחנן בן דהבאי: ארבעה דברים סחו\u0004 (סיפרו) \u0003לי מלאכי השרת: חיגרין, מפני מה הויין\u0004 \u0005[נהיים,\u0006 נוצרים\u0005]\u0006 כך — \u0003מפני ש\u0004הוריהם \u0003הופכים את שולחנם,\u0004 שבאים על האשה שלא בדרך הרגילה. \u0003אילמים מפני מה הויין\u0004 \u0005[נהיים,\u0006 נוצרים\u0005]\u0006 — \u0003מפני שמנשקים\u0004 ההורים \u0003על אותו מקום\u0004 של ערווה. \u0003חרשים מפני מה הויין\u0004 \u0005[נהיים,\u0006 נוצרים\u0005]\u0006 — \u0003מפני שמספרים\u0004 (שמשוחחים) ההורים \u0003בשעת תשמיש. סומין\u0004 (עיוורים) \u0003מפני מה הויין\u0004 \u0005[נהיים,\u0006 נוצרים\u0005]\u0006 — \u0003מפני שמסתכלים\u0004 ההורים \u0003באותו מקום.\u0004","על חלק מדברים האלה שואלים, \u0003ורמינהו\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]:\u0006 \u0003שאלו את אימא שלום\u0004 אשתו של ר' אליעזר בן הורקנוס: \u0003מפני מה\u0004"],["\u0003בניך יפיפין ביותר? אמרה להן:\u0004 בעלי \u0003אינו מספר\u0004 (משוחח) \u0003עמי\u0004 בשעת תשמיש \u0003לא בתחלת הלילה ולא בסוף הלילה אלא בחצות הלילה, וכשהוא מספר\u0004 עמי, הריהו באותה שעה \u0003מגלה טפח\u0004 מן הגוף שלה \u0003ומכסה טפח, ודומה עליו\u0004 כשהוא בא עליה \u0003כמי שכפאו שד,\u0004 כמי שמפחד מן השד שהוא מתכסה כולו מפני הפחד.","\u0003ואמרתי לו\u0004 לבעלי: \u0003מה טעם\u0004 הוא נוהג כך? \u0003ואמר לי: כדי שלא אתן את עיני באשה אחרת,\u0004 ולכן בחר בשעה זו שאין בני אדם מצויים ברחוב, ובאופן זה, כדי שלא יחשוב באשה אחרת. שאם לא כן \u0003ונמצאו בניו באין לידי ממזרות.\u0004 כלומר, שיש כאן כעין ממזרות מצד הנפש אם חושב בשעת תשמיש על אשה אחרת. ומכל מקום אנו למדים שאדם גדול זה היה מספר עם אשתו בשעת תשמיש!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — כשהוא משוחח עימה \u0003במילי\u0004 \u0005[בדברים]\u0006 של \u0003תשמיש\u0004 ואין בכך פגם, \u0003הא\u0004 \u0005[זה]\u0006 שיש בכך פגם — שמדבר איתה \u0003במילי אחרנייתא\u0004 \u0005[בדברים אחרים]\u0006 שאינם שייכים לכך. \u0003אמר ר' יוחנן: זו\u0004 שאמרנו היא \u0003דברי יוחנן בן דהבאי\u0004 בלבד, \u0003אבל אמרו חכמים: אין הלכה כיוחנן בן דהבאי, אלא כל מה שאדם רוצה לעשות באשתו — עושה\u0004 בכל דרך שנוחה לו, ואינו צריך לחשוש לכל אלה. \u0003משל לבשר הבא מבית הטבח, רצה לאכלו במלח — אוכלו,\u0004 רוצה לאכלו \u0003צלי — אוכלו,\u0004 רוצה לאכלו \u0003מבושל — אוכלו,\u0004 או \u0003שלוק — אוכלו, וכן דג הבא מבית הצייד.\u0004","","\u0003אמר אמימר\u0004 כהסבר לדבר: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003מלאכי השרת\u0004 שהזכיר יוחנן בן דהבאי שמפיהם אמר את דבריו — כוונתו היא \u0003רבנן\u0004 \u0005[חכמים],\u0006 שהוא קורא להם בלשון כבוד \"מלאכי השרת\", וראיה לדבר \u0003דאי תימא\u0004 \u0005[שאם תאמר]\u0006 \u0003מלאכי השרת ממש, אמאי\u0004 \u0005[מדוע]\u0006 \u0003אמר ר' יוחנן אין הלכה כיוחנן בן דהבאי? הא אינהו בקיאי\u0004 \u0005[הרי הם,\u0006 המלאכים, \u0005בקיאים]\u0006 \u0003בצורת הולד טפי\u0004 \u0005[יותר]\u0006 מאשר בני אדם, ואם היה הדבר באמת מפי המלאכים — היה צריך להיזהר מכל אלה. ומוסיף: \u0003ואמאי קרו להו\u0004 \u0005[ומדוע קוראים להם]\u0006 לחכמים \u0003מלאכי השרת — דמצייני\u0004 \u0005[ש\u0006הם \u0005מצויינים],\u0006 ניכרים בלבושיהם \u0003כמלאכי השרת.\u0004","ומסופר: \u0003ההיא דאתאי לקמיה\u0004 \u0005[\u0006אשה \u0005אחת שבאה לפני]\u0006 \u0003רבי\u0004 להתלונן על בעלה, \u0003אמרה לו: רבי, ערכתי לו שולחן,\u0004 בלשון נקיה — ששכבה לפניו בשעת הביאה, \u0003והפכו,\u0004 שבא עלי שלא בדרך הרגילה! \u0003אמר לה: בתי, תורה התירתך\u0004 גם בביאה שלא בדרך הרגילה, \u0003ואני מה אעשה ליך\u0004 (לך) אם הוא נוהג כן? וכן, \u0003ההיא דאתאי לקמיה\u0004 \u0005[\u0006אשה \u0005אחת שבאה לפני]\u0006 \u0003רב\u0004 להתלונן על בעלה, \u0003אמרה לו: רבי, ערכתי לו\u0004 לבעלי \u0003שולחן והפכו! אמר: מאי שנא מן ביניתא\u0004 \u0005[מה שונה\u0006 הדבר \u0005מדג]\u0006 שאדם יכול לאכלו בכל דרך שהוא רוצה?","אגב הדברים שנאמרו על ר' אליעזר מביאים: נאמר \u0003\"ולא תתורו אחרי לבבכם\"\u0004 (במדבר טו, לט), \u0003מכאן אמר רבי: אל ישתה אדם בכוס זה ויתן עיניו בכוס אחר,\u0004 כלומר, אל ישמש אדם עם אשה אחת כאשר הוא חושב באותה שעה על אשה אחרת. \u0003אמר רבינא: לא נצרכא\u0004 \u0005[נצרכה]\u0006 לומר כן באשה זרה ממש, \u0003אלא\u0004 ש\u0003אפילו\u0004 הן \u0003שתי נשיו\u0004 והוא משמש עם אחת וחושב על האחרת — יש בכך פגם. נאמר: \u0003\"וברותי מכם המרדים והפושעים בי\"\u0004 (יחזקאל כ, לח), \u0003אמר ר' לוי: אלו בני תשע מדות\u0004 שהם נחשבים משעת יצירתם פגומים ומהם יוצאים מורדים ופושעים, וסימנם: \u0003בני אסנ\"ת משגע\"ח.\u0004","","ופירוטם: \u0003בני אימה —\u0004 שהאשה מפחדת מבעלה ונבעלת לו מחמת האימה, \u0003בני אנוסה —\u0004 שבעלה בא עליה באונס, \u0003בני שנואה —\u0004 שהיא שנואה עליו, \u0003בני נידוי —\u0004 שאחד מהם היה בנידוי, \u0003בני תמורה —\u0004 שחשב על אשה אחת ושימש עם אחרת, \u0003בני מריבה —\u0004 בנים שיצירתם היתה בתוך מריבה בין איש לאשתו, \u0003בני שכרות —\u0004 שיצירתם היתה בזמן שההורים היו שיכורים, \u0003בני גרושת הלב —\u0004 שנולדו לאשה כשבעלה כבר החליט בליבו לגרש אותה, \u0003בני ערבוביא —\u0004 שבא על אשה ואינו יודע על מי בא, \u0003בני חצופה —\u0004 שתובעת את בעלה לתשמיש.","על הדבר האחרון שואלים: \u0003איני\u0004 \u0005[ה\u0006אם \u0005כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' שמואל בר נחמני אמר ר' יונתן: כל אדם שאשתו תובעתו — הויין\u0004 \u0005[יהיו]\u0006 \u0003לו בנים שאפילו בדורו של משה רבינו לא היו כמותם.\u0004 וראיה לדבר, \u0003שנאמר\u0004 כשחיפש משה אחר אנשים שישמשו שופטים, אמר: \u0003\"הבו לכם אנשים חכמים ונבנים\u0004 וידועים לשבטיכם ואשימם בראשיכם\u0003\"\u0004 (דברים א, יג), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בסופו של דבר: \u0003\"ואקח את ראשי שבטיכם\u0004 אנשים חכמים וידועים\u0003\"\u0004 (דברים א, טו), \u0003ולא כתיב\u0004 \u0005[כתוב]\u0006 שם \u0003נבונים,\u0004 שאף משה לא מצא אנשים נבונים בדורו. \u0003ו\u0004לעומת זאת \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"יששכר חמר גרם\"\u0004 (בראשית מט, יד), שקיבלו חכמים שהוא רמז לכך שבא יעקב מן השדה רכוב על חמור, ושמעה לאה ויצאה לקראתו ואמרה לו \"אלי תבוא כי שכור שכרתיך בדודאי בני\" (דברים ל, טז), ומזיווג זה נולד יששכר, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"מבני יששכר יודעי בינה לעתים\"\u0004 (דברי הימים א יב, לג), שמבני יששכר, שאביהם נולד על ידי זה שלאה תבעה את יעקב, היו בנים נבונים. ומכאן שיפה הדבר לבנים שהאשה תובעת את בעלה!","","ומשיבים: הכוונה היא אינה לאשה התובעת בפה ובמילים מפורשות, אלא ב\u0003ההיא דמרציא ארצויי\u0004 \u0005[באשה שמתרצה לפניו]\u0006 ברמז, ומתוך דבריה מבין שהיא רוצה בו, ואז נולדים להם בנים מעולים.","","\u0003ארבעה נדרים התירו חכמים,\u0004 שאין צורך כלל להישאל עליהם, והם: \u0003נדרי זרוזין, ונדרי הבאי, ונדרי שגגות, ונדרי אונסין.\u0004 ומפרשים: \u0003נדרי זרוזין\u0004 שהם נדרים שאדם מזרז את חבירו ומשתמש בהפרזה בלשון נדר. \u0003כיצד? היה מוכר חפץ ואמר \"קונם שאיני פוחת לך\u0004 במחירו \u0003מן הסלע\"\u0004 שהוא ארבעה דינרים, \u0003והלה,\u0004 הקונה, \u0003אומר: \"קונם שאיני מוסיף לך על השקל\"\u0004 שהוא שני דינרים,"],["\u0003שניהם\u0004 בעצם \u0003רוצין\u0004 לגמור את המיקח \u0003בשלשה דינרין,\u0004 ולא התכוונו לנדר, אלא הגזימו בדרך מיקוח בלבד.","שנינו במשנה: \u0003\"ארבעה נדרים התירו חכמים\" כו'. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא בר ממל לר' אמי: אמרת לן\u0004 \u0005[לנו]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יהודה נשיאה: מאן תנא\u0004 \u0005[מי שנה]\u0006 משנה זו ב\u0003ארבעה נדרים —\u0004 שיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר משום\u0004 (בשם) \u0003ר' טרפון\u0004 בענין אנשים שהתערבו ביניהם ואמרו שאם אחד מהם צודק — הוא יהיה נזיר, ש\u0003לעולם אין אחד מהן נזיר, לפי שלא ניתנה נזירות אלא להפלאה.\u0004 כלומר, אין נזירות חלה אלא כשאדם נודר אותה בוודאות ובבירור, ולא מחמת הספק. ואף כאן, כיון שלא היתה כוונתם באמת לידור נדר ולעמוד על דבריהם, אנו אומרים שאינו נדר כלל.","\u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו זו היא שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החלוקים על ר' יהודה, ואולם \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 במשנתנו \u0003\"שניהן רצו\u0004 בשלושה דינרין \u0003\"?\u0004 הלא \u0003\"שניהן רוצין\" קתני\u0004 \u0005[שנה].\u0006 כלומר, אף לדעת חכמים, מתחילה כאשר נדרו לא התכוונו לנדר, ולכן לא היה כאן נדר כלל ולא משום שיש חיסרון בהפלאה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 אם היה המקרה כמו במשנה אבל בשינוי קל, כש\u0003אמר לו\u0004 המוכר בלשון נדר שלא יפחות על \u0003טפי\u0004 \u0005[יותר]\u0006 \u0003מסלע והלה\u0004 (וההוא), הלוקח, \u0003אמר\u0004 אף הוא בלשון נדר שאינו מוסיף על \u0003בציר\u0004 \u0005[פחות]\u0006 \u0003משקל,\u0004 האם \u0003נדרא הוי\u0004 \u0005[נדר הוא]\u0006 שכל אחד עומד בדעתו, \u0003או\u0004 שמא נאמר כי גם זה \u0003זרוזין הוי\u0004 \u0005[הוא]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר כיוצא בזה: \u0003היה\u0004 אדם \u0003מסרב\u0004 (מפציר) \u0003בחבירו שיאכל אצלו,\u0004 והחבר לא רצה \u0003ואמר לו \"קונם ביתך שאני נכנס\",\u0004 או \"קונם \u0003טיפת צונן שאני טועם\u0004 אצלך\" — הרי זה \u0003מותר ליכנס לביתו ולשתות הימנו צונן,\u0004 כיון \u0003שלא נתכוון זה\u0004 הנודר \u0003אלא לשום\u0004 (לשם) \u0003אכילה ושתיה,\u0004 שלא יאכל וישתה ממש בביתו, אבל לא התכוון לדברים שאמרם, ואינם אלא לשון הגזמה בלבד.","\u0003ואמאי\u0004 \u0005[ומדוע]\u0006 תאמר כך? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"טיפת צונן\" קאמר\u0004 \u0005[אמר]!\u0006 \u0003אלא\u0004 חייב אתה לומר כי \u0003משתעי איניש הכי\u0004 \u0005[מדבר אדם כך]\u0006 בלשון הגזמה, שאינו מתכוון למה שהוא אומר. \u0003הכא נמי משתעי איניש הכי\u0004 \u0005[כאן גם כן,\u0006 במוכר ולוקח, \u0005מדבר אדם כך]\u0006 שהוא מגזים בדיבורו ואינו מתכוון ממש לדברים שהוא אומר למרות שדייק בלשונו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא:"],["\u0003מי דמי\u0004 \u0005[האם דומים]\u0006 הדברים? \u0003גבי \"\u0004טיפת \u0003צונן\"\u0004 אנו יודעים כי \u0003צדיקים אומרים מעט ועושין הרבה,\u0004 ולכן מה שחבירו אמר לו \"בוא אצלי ושתה טיפת צונן\" התכוון להרבה יותר מזה, ומתחילה לא היתה הכוונה באמירת \"טיפת צונן\" כמשמעה, ולכן גם כוונת הנודר היתה לומר: אותה \"טיפת צונן\" שאתה מציע לי, כלומר, אותה אכילה מרובה שאתה מציע לי — בה אני נודר, אבל לטעום משהו אני מסכים.","אבל \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003ספיקא\u0004 \u0005[ספק]\u0006 \u0003הוא, דלמא\u0004 \u0005[שמא]\u0006 זה שאמר שאינו נותן \u0003פחות מסלע — ויותר על שקל קאמר\u0004 \u0005[\u0006הוא \u0005אומר],\u0006 שכוונתו בעצם לשלושה דינרים, \u0003וזירוזין הוי\u0004 \u0005[הוא],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003דוקא\u0004 בדיוק \u0003קאמר ונידרא הוי\u0004 \u0005[\u0006הוא \u0005אומר ונדר הוא],\u0006 שבענין זה אינו מוותר. בעיה זו לא נפתרה, והסיכום הוא: \u0003תבעי\u0004 \u0005[תישאל]\u0006 השאלה ותעמוד במקומה.","\u0003אמר רב יהודה אמר רב אסי: ארבעה נדרים הללו\u0004 השנויים במשנתנו בכל זאת \u0003צריכין שאלה לחכם\u0004 שיתיר אותם. \u0003כי אמריתא קמיה\u0004 \u0005[כאשר אמרתי אותה,\u0006 את ההלכה הזו, \u0005לפני]\u0006 \u0003שמואל, אמר: תנא תני\u0004 \u0005[התנא שנה]\u0006 \u0003ארבעה נדרים התירו חכמים\", ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 כי \u0003צריכין שאלה לחכם?!\u0004 זו היתה גירסה אחת של הענין.","ואילו \u0003רב יוסף מתני לה להא שמעתא בהאי לישנא\u0004 \u0005[היה שונה את השמועה הזו בזו הלשון]:\u0006 \u0003אמר רב יהודה אמר רב אסי: אין חכם רשאי להתיר אלא כעין ארבעה נדרים הללו.\u0004 כלומר, כשהנודר לא התכוון לשם נדר כלל, ורק הוציא מפיו לשון נדר, או שנדר בטעות. ומעירים: מכאן למדים כי הוא \u0003קסבר\u0004 \u0005[סבור]\u0006 ש\u0003אין פותחין בחרטה,\u0004 כלומר, שבהתרת נדרים אין החכם משתמש בנימוק של חרטה בלבד כדי להתיר (\"לפתוח\") את הנדר, אלא מחדש פתח אחר, ובו מתברר שאם היה מעלה הנודר דבר זה בדעתו לא היה נודר מתחילה.","לעומת זאת מסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[\u0006אדם \u0005אחד שבא לפני]\u0006 \u0003רב הונא\u0004 כדי שיתיר לו את נדרו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003לבך עלך\u0004 \u0005[עליך],\u0006 כלומר, האם אתה עומד עדיין באותה דעה, באותו רצון שהיו לך אז, כשנדרת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא, ושרייה\u0004 \u0005[והתירו]\u0006 רב הונא.","כיוצא בזה \u0003ההוא דאתא לקמיה\u0004 \u0005[\u0006אדם \u0005אחד שבא לפני]\u0006 \u0003רבה בר רב הונא\u0004 שיתיר לו את נדרו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אילו היו עשרה בני אדם שיפייסוך באותה שעה מי נדרת\u0004 \u0005[האם היית נודר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא, והתירו.\u0004","כיוצא בזה \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: אומרים לו\u0004 החכמים המתירים את הנדר \u0003לאדם\u0004 שנדר: \u0003לב זה\u0004 (דעה זו, רצון זה) שהיה לך בשעה שנדרת, האם הוא עדיין \u0003עליך\u0004 (אצלך)? \u0003אם אמר \"לאו\"\u0004 \u0005[לא] —\u0006 \u0003מתירין אותו. ר' ישמעאל בר' יוסי אומר משום\u0004 (בשם) \u0003אביו: אומרים לו לאדם\u0004 שנדר: \u0003אילו היו עשרה בני אדם שיפייסוך באותה שעה מי נדרת\u0004 \u0005[האם היית נודר]?\u0006 \u0003אם אמר \"לאו\"\u0004 \u0005[לא] —\u0006 \u0003מתירין אותו.\u0004","\u0003(סימן: אסי ואלעזר, יוחנן וינאי).\u0004","ועוד מסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[\u0006אדם \u0005אחד שבא לפני]\u0006 \u0003ר' אסי\u0004 להתיר נדרו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כדו תהית\u0004 \u0005[האם אתה מתחרט]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"לא\"?!\u0004 כלומר, ודאי אני מתחרט, \u0003ושרייה\u0004 \u0005[והתירו].\u0006 וכן \u0003ההוא דאתא לקמיה\u0004 \u0005[\u0006אדם \u0005אחד שבא לפני]\u0006 \u0003ר' אלעזר, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בעית נדור\u0004 \u0005[\u0006האם באמת \u0005רצונך היה לנדור]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אילו לא\u0004 היו \u0003מרגזין\u0004 (מרגיזים) \u0003לי — לא בעינן\u0004 \u0005[הייתי רוצה]\u0006 \u0003כלום\u0004\u0005.\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תהא כבעית\u0004 \u0005[יהא זה כפי\u0006 ש\u0005אתה רוצה]\u0006 שלא לנדור, והנדר הותר. ועוד: \u0003ההיא איתתא דאדרתה לברתה\u0004 \u0005[אשה אחת שהדירה\u0006 את \u0005בתה]\u0006 שלא תיהנה ממנה, \u0003אתאי\u0004 \u0005[באה]\u0006 האם \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן\u0004 להתיר נדרה. \u0003אמר לה: אילו הוה ידעת דאמרן מגירתיך עלה דברתך\u0004 \u0005[היית יודעת שאומרות שכנותייך על בתך]:\u0006"],["\u0003אילו לא חמאת\u0004 \u0005[היתה רואה]\u0006 \u0003בה אימה מילין דעזיבה\u0004 \u0005[דברים\u0006 גרועים \u0005ש\u0006ראוי \u0005לעוזבם]\u0006 — \u0003בכדי\u0004 \u0005[לחינם]\u0006 \u0003לא אדרתה\u0004 \u0005[היתה מדירה אותה]!\u0006 אם היית חושבת על כך בשעת הנדר \u0003מי אדרתה\u0004 \u0005[האם היית מדירה אותה]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לא, ושרייה\u0004 \u0005[והתיר אותה].\u0006","מסופר: \u0003בר ברתיה\u0004 \u0005[בן בתו]\u0006 של \u0003ר' ינאי סבא\u0004 \u0005[הזקן]\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 סבו \u0003ר' ינאי סבא\u0004 שיתיר לו נדר, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אילו הוה ידעת\u0004 \u0005[היית יודע]\u0006 שבשעה שאתה נודר \u0003דפתחין\u0004 \u0005[שפותחים]\u0006 בשמים את \u0003פינקסך וממשמשין\u0004 (ומפשפשים) \u0003בעובדך\u0004 \u0005[במעשיך]\u0006 מה טיבם, \u0003מי נדרת\u0004 \u0005[האם היית נודר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא, ושרייה\u0004 \u0005[והתירו].\u0006","\u0003אמר ר' אבא: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המרמז לענין זה — שנאמר: \u0003\"ואחר נדרים לבקר\"\u0004 (משלי כ, כה), שאחרי שאדם נודר מבקרים בשמים את מעשיו. ומעירים: \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003פתח ר' ינאי ליה\u0004 \u0005[לו]\u0006 בפתח זה — \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003לא פתחינן ליה\u0004 \u0005[פותחים לו]\u0006 לאדם הנודר \u0003בהא\u0004 \u0005[בזה],\u0006 לשאול אם אינו מתחרט עליהם משום שהנודר נבדק בידי שמים, כי יש לחשוש שאם יישאל אדם על נדרו כך, יתבייש לומר שאינו מתחרט ויאמר שלא כנכון, שהוא מתחרט.","\u0003ו\u0004כן \u0003לא פתחינן\u0004 \u0005[פותחים אנו]\u0006 \u0003בהדא אחרנייתא\u0004 \u0005[בזו האחרת]\u0006 ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: מאי\u0004 \u0005[במה]\u0006 \u0003פתח ליה\u0004 \u0005[לו]\u0006 \u0003רבן גמליאל לההוא סבא\u0004 \u0005[לזקן אחד]\u0006 שנדר נדר, ובא לפניו כדי להתירו, אמר לו: נאמר \u0003\"יש בוטה כמדקרות חרב ולשון חכמים מרפא\"\u0004 (משלי יב, יח), ופירושו: \u0003כל הבוטה,\u0004 כלומר כל המוציא מפיו ביטוי של נדר — \u0003ראוי לדוקרו בחרב, אלא\u0004 שיש לפניו דרך אחרת — \u0003לשון חכמים מרפא,\u0004 שמתירים לו החכמים את נדרו. וגם בדבר זה אין פותחים.","\u0003ולא פתחינן\u0004 \u0005[פותחים אנו]\u0006 לנודר \u0003בהדא אחרנייתא\u0004 \u0005[בזו האחרת],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נתן אומר: הנודר\u0004 — \u0003כאילו בנה במה\u0004 שלא במקום המקדש, \u0003והמקיימו\u0004 את הנדר הזה — \u0003כאילו מקריב עליו קרבן,\u0004 שהרי לא זו בלבד שנדר, אלא אף גומר את המעשה, ומקיים את מה שנדר. \u0003ברישא פתחינן\u0004 \u0005[ב\u0006דבר \u0005הראשון אנו פותחים]\u0006 ואומרים לו לאדם שנדר: דע לך שכל הנודר עושה מעשה רע כבונה במה. ואילו \u0003בסיפא\u0004 \u0005[ב\u0006ענין \u0005האחרון]\u0006 שהמקיים את הנדר כאילו מקריב עליו קרבן נחלקו חכמים, \u0003אביי אמר: פתחינן\u0004 \u0005[פותחים אנו],\u0006 ו\u0003רבא אמר: לא פתחינן\u0004 \u0005[פותחים אנו]\u0006 בפתח זה.","\u0003רב כהנא מתני לה להא שמעתא בהדין לישנא\u0004 \u0005[היה שונה את השמועה הזו בלשון זו]\u0006 שאמרנו. ואילו \u0003רב טביומי מתני הכי\u0004 \u0005[היה שונה אותה כך]:\u0006 במה שכתוב \u0003בסיפא לא פתחינן\u0004 \u0005[בסוף אין אנו פותחים]\u0006 לכל הדעות, שאין אומרים לו לאדם שהמקיים נדר עושה מעשה רע. ואילו לגבי הנימוק ש\u0003ברישא\u0004 \u0005[בהתחלה]\u0006 נחלקו, \u0003אביי אמר: פתחינן\u0004 \u0005[פותחים אנו]\u0006 בזה, \u0003רבא אמר: לא פתחינן\u0004 \u0005[פותחים אנו].\u0006 ומסכמים, \u0003והלכתא\u0004 \u0005[וההלכה\u0006 היא\u0005]:\u0006 \u0003לא פתחינן\u0004 \u0005[פותחים אנו]\u0006 \u0003לא\u0004 במה שכתוב \u0003ברישא\u0004 \u0005[בתחילה]\u0006 \u0003ולא\u0004 במה שכתוב \u0003בסיפא\u0004 \u0005[בסוף].\u0006","ועוד: \u0003ולא פתחינן\u0004 \u0005[פותחים אנו]\u0006 \u0003בהא נמי\u0004 \u0005[גם כן בזה]\u0006 של \u0003שמואל.\u0004 ש\u0003אמר שמואל:\u0004 הנודר נדר, \u0003אף על פי שמקיימו — נקרא רשע. אמר ר' אבהו: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המלמד על כך — שנאמר: \u0003\"וכי תחדל לנדר לא יהיה בך חטא\"\u0004 (דברים כג, כג), \u0003ויליף\u0004 \u0005[ולומד]\u0006 \u0003\"חדלה\" \"חדלה\"\u0004 בגזירה שווה; \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"וכי תחדל לנדר\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"שם רשעים חדלו רגז\"\u0004 (איוב ג, יז), לומר שהנודר ומקיים עושה בזה ענין של רשע.","\u0003אמר רב יוסף: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 דבר זה במשנה מפורשת: האומר שהוא נודר \u0003\"כנדרי כשרים\" — לא אמר כלום, \"כנדרי רשעים\" — נדר בנזיר ובקרבן ובשבועה.\u0004 ומכאן יש ללמוד שנדר הוא מעשה רשעים.","אגב הזכרת הכתוב \"שם רשעים חדלו רוגז\", מביאים מה ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: כל הכועס כל מיני גיהנם שולטין בו,\u0004 לפי שהכעס גורם לו לעבור על עבירות חמורות, \u0003שנאמר: \"והסר כעס מלבך והעבר רעה מבשרך\"\u0004 (קהלת יא, י), \u0003ואין \"רעה\"\u0004 האמורה \u0003אלא גיהנם, שנאמר: \"כל פעל ה' למענהו וגם רשע ליום רעה\"\u0004 (משלי טז, ד), כלומר, בסופו של דבר, יומו של הרשע מגיע בגיהנם.","\u0003ולא עוד אלא ש\u0004כל הכועס מחלות \u0003התחתוניות\u0004 (טחורים) \u0003שולטות בו, שנאמר: \"ונתן ה' לך שם לב רגז וכליון עינים ודאבון נפש\"\u0004 (דברים כח, סה), \u0003איזהו דבר,\u0004 מחלה, \u0003שמכלה את העינים\u0004 בכאב \u0003ומדאיב\u0004 (ומצער) \u0003את הנפש — הוי אומר — אלו התחתוניות.\u0004","מסופר: \u0003עולא במיסקיה לארעא דישראל איתלוו ליה תרין\u0004 \u0005[בעלייתו לארץ ישראל התלוו לו שני]\u0006 אנשים מ\u0003בני חוזאי בהדיה\u0004 \u0005[יחד איתו].\u0006 בתוך קטטה שהיתה ביניהם \u0003קם חד שחטיה לחבריה\u0004 \u0005[עמד אחד\u0006 ו\u0005שחט את חבירו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הרוצח \u0003לעולא: יאות עבדי\u0004 \u0005[יפה עשיתי]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003ופרע ליה\u0004 \u0005[ופתח לו]\u0006 את \u0003בית השחיטה,\u0004 כלומר, חתוך אותו עוד כדי שימות מהר. \u0003כי אתא לקמיה\u0004 \u0005[כאשר בא\u0006 עולא \u0005לפני]\u0006 \u0003ר' יוחנן\u0004 וסיפר לו על כך, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003חס ושלום אחזיקי\u0004 \u0005[החזקתי]\u0006 \u0003ידי עוברי עבירה\u0004 בזה שאמרתי לו דברים אלה? אף על פי שמחמת האימה שיהרגהו אמר כך. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נפשך הצלת\u0004 בכך, שמותר לו לאדם לומר דברים כאלה כדי להציל את עצמו ממוות.","לעצם הסיפור הזה \u0003קא תמה\u0004 \u0005[היה תמה]\u0006 \u0003ר' יוחנן: מכדי כתיב\u0004 \u0005[הלא נאמר]\u0006 בפרשת הקללות: \u0003\"ונתן ה' לך שם לב רגז\"\u0004 (דברים כח, סה) ודבר זה הלא \u0003בבבל כתיב\u0004 \u0005[נאמר],\u0006 ששם במקום הגלות יש לב רגז וכועס, ואיך ייתכן שבארץ ישראל יזדמן שיכעס אדם כל כך עד שירצח את חבירו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא: \u0003ההוא שעתא\u0004 \u0005[באותה שעה]\u0006 שאירע הדבר"],["\u0003לא עברינן ירדנא\u0004 \u0005[עברנו\u0006 את \u0005הירדן]\u0006 ואם כן עדיין בחוץ לארץ היינו, ושם הוא המקום לקללת \"לב רגז\".","\u0003אמר רבה בר רב הונא: כל הכועס,\u0004 באותה שעה \u0003אפילו שכינה אינה חשובה כנגדו, שנאמר: \"רשע כגבה אפו בל ידרש אין אלהים כל מזמותיו\"\u0004 (תהלים י, ד). \u0003ר' ירמיה מדיפתי אמר:\u0004 כל הכועס \u0003משכח תלמודו ומוסיף טיפשות, שנאמר: \"כי כעס בחיק כסילים ינוח\"\u0004 (קהלת ז, ט), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וכסיל יפרש אולת\"\u0004 (משלי יג, טז), כיון שהכועס נעשה כסיל, הריהו פורס ומגדיל את האיוולת. \u0003רב נחמן בר יצחק אמר:\u0004 הכועס \u0003בידוע שעונותיו מרובין מזכיותיו, שנאמר: \"ובעל חמה רב פשע\"\u0004 (משלי כט, כב).","\u0003אמר רב אדא ברבי חנינא: אלמלא (לא) חטאו ישראל\u0004 בזמנם \u0003לא ניתן להם אלא חמשה חומשי תורה וספר יהושע בלבד,\u0004 ומדוע ספר יהושע — \u0003שערכה של ארץ ישראל הוא,\u0004 יש בו חלוקת ארץ ישראל לנחלת השבטים ולכן היה בו צורך לדורות. אבל שאר ספרי הנביאים הם בעצם תולדה של מה שהכעיסו את הקדוש ברוך הוא ושלח נביאים להוכיח אותם. \u0003מאי טעמא\u0004 \u0005[מה טעם,\u0006 רמז\u0005]\u0006 הדבר — שנאמר: \u0003\"כי ברב חכמה רב כעס\"\u0004 (קהלת א, יח), כלומר, רוב החכמה שיש לנו בקבלת כל ספרי המקרא היא תוצאה של רוב כעס שהכעסנו את הקדוש ברוך הוא.","\u0003אמר ר' אסי: אין נזקקין\u0004 להתיר \u0003ל\u0004מי שנדר נדר ונשבע ב\u0003\"אלהי ישראל\",\u0004 לפי שהוא נדר חמור, שהוציא מפיו שבועה בשם ה', \u0003חוץ מ\u0004מקרה שנשבע ב\"אלוקי ישראל\" ואמר \u0003\"קונם אשתי נהנית לי\u0004 משום \u0003שגנבה את כיסי\u0004 (ארנקי) או \u0003שהכתה את בני\" ונודע שלא גנבה ושלא הכתו,\u0004 שבכגון זה נזקקים לו כיון שהיה זה נדר טעות, אבל במקרה אחר אין נזקקים למי שנשבע כך.","מסופר: \u0003ההיא דאתאי לקמיה\u0004 \u0005[\u0006אשה \u0005אחת שבאה לפני]\u0006 \u0003רב אסי\u0004 שיתיר לה את נדרה, \u0003אמר לה: במאי\u0004 \u0005[במה]\u0006 באיזו לשון \u0003נדרת?\u0004 אמרה לו: \u0003ב\"אלהי ישראל\". אמר לה: אי נדרת\u0004 \u0005[אם היית נודרת]\u0006 ואומרת \u0003ב\"מוהי\" שהיא כינוי בעלמא\u0004 \u0005[סתם]\u0006 — \u0003מזדקיקנא\u0004 \u0005[הייתי מזדקק]\u0006 \u0003לך\u0004 להתיר את הנדר, \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003לא נדרת ב\"מוהי\" אלא ב\"אלהי ישראל\" — לא מזדקיקנא\u0004 \u0005[איני מזדקק]\u0006 \u0003לך\u0004 להתיר לך את הנדר.","מסופר: \u0003רב כהנא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב יוסף, אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003לטעום מר מידי\u0004 \u0005[שיטעם אדוני דבר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 בשם \u0003מרי כולא\u0004 \u0005[אדון הכל]\u0006 \u0003לא טעימנא ליה\u0004 \u0005[אין אני טועם אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003לא מרי כולא\u0004 \u0005[אדון הכל]\u0006 \u0003לא טעימת ליה\u0004 \u0005[אין אתה טועם אותו].\u0006 ומעירים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 ניתן להבין את דברי \u0003רב כהנא\u0004 ש\u0003אמר\u0004 בלשון שבועה — \u0003\"לא מרי כולא\u0004 \u0005[אדון הכל]\u0006 \u0003\"\u0004שאיננו טועם, \u0003אלא לרב יוסף אמאי\u0004 \u0005[מדוע]\u0006 \u0003אמר \"לא מרי כולא\u0004 \u0005[אדון הכל]\u0006 \u0003\"?\u0004 וכי על מה היה לו להישבע! ומשיבים: \u0003הכי הוא דקאמר ליה\u0004 \u0005[כך הוא שאמר לו]:\u0006 כיון ש\u0003\"לא מרי כולא\" הוא דקאמרת\u0004 \u0005[שאמרת],\u0006 \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003לא טעימת ליה\u0004 \u0005[תטעם אותו],\u0006 משום שאין נזקקים להתיר נדר שנאמר בלשון חמורה זו.","\u0003אמר רבא אמר רב נחמן:\u0004 סיכום \u0003הלכתא\u0004 \u0005[ההלכה]\u0006 בענין זה: \u0003פותחין\u0004 לו לאדם אף \u0003בחרטה,\u0004 שמקדים החכם ושואל אם הוא מתחרט על מה שנדר בשעתו, \u0003ונזקקין\u0004 גם \u0003ל\u0004מי שנדר בלשון \u0003\"אלהי ישראל\".\u0004","מסופר: היה \u0003משתבח ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן ברב סחורה\u0004 תלמידו ש\u0003אדם גדול הוא. אמר לו\u0004 רב נחמן: \u0003כשיבא\u0004 רב סחורה \u0003לידך\u0004 (אליך), \u0003הביאהו לידי\u0004 (אלי). \u0003הוה ליה נדרא למישרא\u0004 \u0005[היה לו\u0006 לרב סחורה \u0005נדר להתיר]\u0006 וכיון שידע רבא שרב נחמן רוצה לראות את רב סחורה, שלח אותו אליו. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב נחמן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן כשרצה להתיר לו: \u0003נדרת אדעתא דהכי\u0004 \u0005[על דעת כך\u0006 וכך\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 ולא התיר לו נדרו. שאל אותו שוב: \u0003אדעתא דהכי\u0004 \u0005[על דעת כך]?\u0006 והציע אפשרות אחרת — אמר לו: \u0003אין\u0004 \u0005[כן].\u0006 וכך היה \u0003כמה זימנין\u0004 \u0005[פעמים],\u0006 שבכל פעם שהציע לו רב נחמן פתח, אמר רב סחורה שכבר בשעת הנדר חשב על כך, ונדר על מנת כן. \u0003איקפד\u0004 \u0005[הקפיד]\u0006 \u0003רב נחמן\u0004 עליו, שנראה לו שרב סחורה מעמיד קשיים מיותרים בפניו שלא יוכל להתיר לו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל לקילעך\u0004 \u0005[לך לאוהלך],\u0006 אין אני רוצה לדבר איתך, משום שכעס עליו.","\u0003נפק\u0004 \u0005[יצא]\u0006 \u0003רב סחורה ופתח פיתחא לנפשיה\u0004 \u0005[פתח לעצמו]\u0006 שתהא דרך להתיר את נדרו. כיצד? \u0003רבי אומר: איזה היא דרך ישרה שיבור\u0004 (שיבחר) \u0003לו האדם — כל שהיא תפארת לעושיה ותפארת לו מן האדם. והשתא דאיקפד\u0004 \u0005[ועכשיו שהקפיד]\u0006 \u0003רב נחמן\u0004 עלי — \u0003אדעתא דהכי\u0004 \u0005[על דעת כן]\u0006 \u0003לא נדרי\u0004 \u0005[נדרתי],\u0006 שנמצא שאין זו תפארת מן האדם. \u0003ושרא לנפשיה\u0004 \u0005[והתיר לעצמו]\u0006 את הנדר, שמעתה אפשר להתירו, משום שלא נדר על מנת שיכעס עליו אדם גדול זה.","בדומה לזה מסופר: \u0003ר' שמעון ברבי\u0004 (בנו של רבי) \u0003הוה ליה נדרא למישרא\u0004 \u0005[היה לו נדר להתיר],\u0006 \u0003אתא לקמייהו דרבנן\u0004 \u0005[בא לפני חכמים]\u0006 להתיר, \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003נדרת אדעתא דהכי\u0004 \u0005[על דעת כך\u0006 וכך\u0005]?\u0006 \u0003אמר: אין\u0004 \u0005[כן].\u0006 הציעו אפשרות אחרת: \u0003אדעתא דהכי\u0004 \u0005[על דעת כך]?\u0006 אמר להם: \u0003אין\u0004 \u0005[כן].\u0006 וכך היה \u0003כמה זימנין\u0004 \u0005[פעמים]\u0006"],["\u0003והוו מצטערי רבנן משימשא לטולא ומטולא לשימשא\u0004 \u0005[והיו מצטערים חכמים\u0006 ויוצאים \u0005מ\u0006מקום בו יש \u0005שמש\u0006 ועוברים \u0005לצל, ומצל לשמש],\u0006 שנמשך הדבר זמן מרובה והיו החכמים צריכים לעבור ממקום למקום במשך זמן זה, שלא ידעו כיצד להתיר לו.","\u0003(לישנא אחרינא\u0004 \u0005[לשון אחרת],\u0006 שאלו אותו: \u0003אדעתא דהכי\u0004 \u0005[על דעת כך]\u0006 נדרת? אמר להם: \u0003אין\u0004 \u0005[כן].\u0006 וכך היה \u0003כמה זימנין\u0004 \u0005[פעמים]\u0006 \u0003והוו מצטערי רבנן משימשא לטולא ומטולא לשימשא\u0004 \u0005[והיו מצטערים חכמים משמש לצל ומצל לשמש]\u0006 ולא מצאו פתרון).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בטנית בריה\u0004 \u0005[בנו]\u0006 של \u0003אבא שאול בן בטנית: מי\u0004 \u0005[האם]\u0006 \u0003נדרת אדעתא דמצטערי רבנן מטולא לשימשא ומשימשא לטולא\u0004 \u0005[על דעת שיצטערו חכמים\u0006 בגללך עד כדי הליכה \u0005מצל לשמש ומשמש לצל]?\u0006 \u0003אמר: לא, ושריוה\u0004 \u0005[והתירוהו].\u0006","מסופר: \u0003ר' ישמעאל בר\u0004 \u0005[בן]\u0006 \u0003ר' יוסי הוה ליה נדרא למישרא\u0004 \u0005[היה לו נדר להתיר].\u0006 \u0003אתא לקמייהו דרבנן\u0004 \u0005[בא לפני חכמים],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003נדרת אדעתא דהכי\u0004 \u0005[על דעת כך\u0006 וכך\u0005]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 \u0003נדרתא אדעתא דהכי\u0004 \u0005[נדרת על דעת כך]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 וכך היה \u0003כמה זימנין\u0004 \u0005[פעמים].\u0006 \u0003כיון דחזא ההוא קצרא\u0004 \u0005[שראה כובס אחד]\u0006 שגורם ר' ישמעאל לכך \u0003דמצטערי רבנן\u0004 \u0005[שמצטערים חכמים]\u0006 שאינם מוצאים פתרון לנדרו, \u0003מחייה באוכלא דקצרי\u0004 \u0005[היכה אותו,\u0006 את ר' ישמעאל, \u0005בכלי הכובסים]\u0006 שבידו. \u0003אמר\u0004 ר' ישמעאל עצמו: \u0003אדעתא דמחי לי קצרא\u0004 \u0005[על דעת שיכה אותי הכובס]\u0006 בגלל נדרי \u0003לא נדרי\u0004 \u0005[נדרתי],\u0006 \u0003ושריה לנפשיה\u0004 \u0005[והתירו לעצמו],\u0006 שמעתה יוכל חכם להתיר את נדרו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא: האי\u0004 \u0005[זה]\u0006 הרי \u0003נולד הוא,\u0004 הרי אירע מאורע חדש שלא היה כלול בדברים שחשב עליהם בשעה שנדר, שהרי \u0003לא מסיק אדעתא דמחי ליה קצרא\u0004 \u0005[העלה על דעתו שיכה אותו הכובס].\u0006 \u0003ותנינא\u0004 \u0005[ו\u0006הלא \u0005שנינו]\u0006 ש\u0003אין פותחין לו\u0004 לנודר להתיר את נדרו \u0003בנולד,\u0004 שאין פותחים פתח לנדר על סמך מצב חדש שלא היה קיים בשעת הנדר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003האי לאו\u0004 \u0005[זה לא]\u0006 \u0003נולד הוא,\u0004 שאינו נחשב נולד שלא יכול להעלות הדבר בדעתו מתחילה, כיון \u0003דשכיחי אפיקורי דמצערי רבנן\u0004 \u0005[שמצויים אפיקורסים שמצערים\u0006 את ה\u0005חכמים]\u0006 ולכן אין לראות דבר זה בגדר \"נולד\".","מסופר: \u0003דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003אביי הוה\u0004 \u0005[היתה]\u0006 \u0003לה ההיא ברתא\u0004 \u0005[בת].\u0006 \u0003הוא,\u0004 אביי, \u0003אמר:\u0004 תינשא בת זו \u0003לקריבאי\u0004 \u0005[לקרובי],\u0006 לקרוב משפחה שלו, ואילו \u0003היא,\u0004 אשתו, \u0003אמרה\u0004 שתינשא \u0003לקריבה\u0004 \u0005[לקרוב שלה].\u0006 \u0003אמר לה\u0004 אביי: \u0003תיתסרא\u0004 \u0005[תיאסר]\u0006 \u0003הנאתי עלך\u0004 \u0005[עליך]\u0006 \u0003אי עברת אדעתאי ומינסבת לה לקריבך\u0004 \u0005[אם את עוברת על דעתי ומשיאה אותה לקרובך].\u0006 \u0003אזלת ועברת\u0004 \u0005[הלכה ועברה]\u0006 \u0003על דעתיה\u0004 \u0005[דעתו]\u0006 \u0003ואינסבא לקריבה\u0004 \u0005[ונישאה\u0006 הבת \u0005לקרובה\u0006 של אמה\u0005].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 אביי \u0005לפני]\u0006 \u0003רב יוסף. אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אילו הוה ידעת\u0004 \u0005[היית יודע]\u0006 \u0003דעברת על דעתך ומנסבא לה לקריבה מי אדרתה\u0004 \u0005[ש\u0006היא \u0005עוברת\u0006 בסופו של דבר \u0005על דעתך ומשיאה אותה לקרובה, האם היית מדיר אותה]?\u0006 \u0003אמר\u0004 לו אביי: אכן באופן כזה \u0003לא\u0004 הייתי מדירה. \u0003ושרייה\u0004 \u0005[והתירו]\u0006 \u0003רב יוסף.\u0004 שרואים את הנדר בגדר איום בלבד, שלא חשב שיגיע הדבר שתיאסר אשתו עליו.","ושואלים: \u0003ומי שרי כי האי גוונא\u0004 \u0005[והאם מותר באופן זה]?\u0006 שהרי עיקרו של הנדר היה שלא תשיא את הבת לקרוב שלה! ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה באדם אחד שהדיר את אשתו מלעלות לרגל, ועברה על דעתו ועלתה לרגל. ובא לפני ר' יוסי\u0004 להתירו. \u0003אמר לו: ואילו היית יודע שעוברת על דעתך ועולה לרגל כלום הדרתה? אמר לו: לא, והתירו ר' יוסי.\u0004 משמע שאף זה הוא פתח ראוי להתיר נדר.","\u0003ר' אליעזר בן יעקב אומר: אף הרוצה להדיר את חבירו שיאכל אצלו,\u0004 אבל אינו רוצה לידור נדר ממש אלא כל רצונו שחבירו ייענה להזמנתו, \u0003יאמר לו\u0004 מתחילה: \u0003\"כל נדר שאני עתיד לידור הוא בטל\", ובלבד שיהא זכור בשעת הנדר\u0004 שדעתו מתחילה היתה לבטלו.","על הצעתו של ר' אליעזר בן יעקב תוהים: \u0003ו\u0004הלא \u0003כיון דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]\u0006 \u0003\"כל נדר שאני עתיד לידור יהא בטל\" לא שמע ליה\u0004 \u0005[ישמע לו]\u0006 \u0003ולא אתי בהדיה\u0004 \u0005[יבוא אצלו]!\u0006 שאם החבר יודע מראש שנדר זה אין בו ממש, מדוע ישמע בקולו?"],["\u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 היא \u0005שנויה]:\u0006 \u0003הרוצה שיאכל אצלו חבירו ומסרב בו\u0004 (מזרז אותו) \u0003ומדירו — נדרי זירוזין הוא\u0004 שאינם צריכים התרה. \u0003והרוצה שלא יתקיימו נדריו כל השנה, יעמוד בראש השנה ויאמר: כל נדר שאני עתיד לידור\u0004 בשנה זו \u0003יהא בטל, ובלבד שיהא זכור בשעת הנדר.\u0004","ותוהים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003זכור\u0004 באותה שעה שנודר שאמר שהוא מבוטל, ובכל זאת הוא נודר, נמצא ש\u0003עקריה לתנאיה\u0004 \u0005[ש\u0006הוא \u0005עוקר את תנאו]\u0006 שכל נדריו יתבטלו, \u0003וקיים ליה לנדריה\u0004 \u0005[ומקיים את נדרו]!\u0006 \u0003אמר אביי, תני\u0004 \u0005[שנה]\u0006 כך: \u0003ובלבד שלא יהא זכור בשעת הנדר\u0004 שעשה תנאי כזה, ואז הנדר בטל.","\u0003רבא אמר: לעולם\u0004 תאמר \u0003כדאמרינן מעיקרא\u0004 \u0005[כפי שאמרנו מתחילה]\u0006 ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שהתנה\u0004 תנאי של ביטול נדרים \u0003בראש השנה\u0004 לגבי נדרי כל השנה, \u0003ולא ידע במה,\u0004 באלו נדרים, \u0003התנה. והשתא קא נדר\u0004 \u0005[ועכשיו\u0006 הוא \u0005נודר].\u0006 \u0003אי\u0004 \u0005[אם]\u0006 היה \u0003זכור בשעת הנדר ואמר \"על דעת הראשונה אני נודר\",\u0004 שאם נדר זה שאני נודר הוא בכלל מה שהתניתי — אין אני חפץ בו, הרי במקרה זה \u0003נדריה לית ביה ממשא\u0004 \u0005[נדרו אין בו ממש]\u0006, ואם \u0003לא אמר \"על דעת הראשונה אני נודר\" — עקריה לתנאיה\u0004 \u0005[עקר את תנאו]\u0006 \u0003וקיים לנדריה\u0004 \u0005[את נדרו].\u0006","מסופר: \u0003רב הונא בר חיננא סבר למידרשיה בפירקא\u0004 \u0005[חשב לדורשו,\u0006 את הדבר הזה \u0005בדרשת הרגל]\u0006 כדי שילמדו הכל דרך זו של התרת נדרים בראש השנה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 ה\u0003תנא קא מסתים לה סתומי\u0004 \u0005[סותם את\u0006 הדבר ה\u0005זה\u0006 במשנתנו\u0005]\u0006 ואינו אומר אותו במפורש, כלומר, שאפילו במשנה שהיא נלמדת על ידי תלמידי חכמים לא פירשו דבר זה, \u0003כדי שלא ינהגו\u0004 הציבור \u0003קלות ראש בנדרים. ואת דרשת ליה בפירקא\u0004 \u0005[ואתה דורש אותה\u0006 בציבור \u0005בדרשת הרגל]?!\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו]\u0006 על \u0003ר' אליעזר בן יעקב\u0004 במשנתנו, \u0003או לא? ואם תמצא לומר פליגי\u0004 \u0005[\u0006ש\u0005חלוקים\u0006 עליו\u0005],\u0006 האם \u0003הלכתא כותיה\u0004 \u0005[הלכה כמותו],\u0006 \u0003או לא?\u0004 ומביאים ראיה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003האומר לחבירו\u0004"],["\u0003\"קונם שאיני נהנה לך\u0004 (ממך) \u0003אם אי\u0004 (אין) \u0003אתה נוטל,\u0004 מקבל במתנה, \u0003לבנך כור של חיטין ושתי חביות של יין\" — הרי זה יכול להתיר את נדרו שלא על פי חכם, שיכול\u0004 האיש שרצה הנודר לתת לבנו מתנה \u0003לומר לו\u0004 לנודר: \u0003כלום אמרת\u0004 לתת לבני \u0003אלא בשביל כבודי — זה הוא כבודי\u0004 שלא אטול.","ונדייק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא \u0003דאמר\u0004 \u0005[שאומר]\u0006 האיש שצריך לקבל \u0003\"זה הוא כבודי\", הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא\u0006 אומר \u0005כן]\u0006 — \u0003נדר הוא.\u0004 ונברר, \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שדעת \u0003ר' אליעזר בן יעקב —\u0004 הלא \u0003נדרי זירוזין הוי\u0004 \u0005[הם],\u0006 שלא נתכוון לנדר, אלא לזרזו שיטול ממנו את המתנה, ואינם נדרים כלל. \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו]\u0006 וסבורים שנדרי זירוזין גם הם נדרים.","ודוחים: \u0003לעולם\u0004 שיטת \u0003ר' אליעזר בן יעקב היא, ו\u0004אולם \u0003מודה ר' אליעזר בן יעקב בהאי דנדרא הוי\u0004 \u0005[בזה שנדר הוא]\u0006 ולא רק לזרזו, \u0003דאמר ליה\u0004 \u0005[שאומר לו\u0006 הנודר\u0005]:\u0006 \u0003לא כלבא אנא דמיתהנינא מינך ולא מיתהנית מינאי\u0004 \u0005[אין אני כלב, שאני נהנה ממך ואין אתה נהנה ממני]\u0006 והוא עומד באמת על כך שיקבל דבר ממנו, ואין זה נחשב זירוז בלבד.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003האומר לחבירו \"קונם שאתה נהנית לי\u0004 (ממני) \u0003אם אי\u0004 (אין) \u0003אתה נותן לבני\u0004 במתנה \u0003כור של חיטין ושתי חביות של יין\", ר' מאיר אומר:\u0004 באיסור נדר הוא עומד ואסור בהנאתו \u0003עד שיתן. וחכמים אומרים: אף זה\u0004 הנודר \u0003יכול להתיר את נדרו שלא על פי חכם, שיכול לומר: הריני כאילו התקבלתי\u0004 (קיבלתי ממך).","ונדייק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא \u0003דאמר\u0004 \u0005[שאומר]\u0006 \u0003\"הריני כאילו התקבלתי\", הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא\u0006 אומר \u0005כן]\u0006 — \u0003נדר הוא.\u0004 ונברר: דברי חכמים כאן \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהם כדעת \u0003ר' אליעזר בן יעקב —\u0004 הלא \u0003נדרי זירוזין הוי\u0004 \u0005[הם],\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מוכח שהוא שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003ו\u0004נמצא כי \u0003פליגי\u0004 \u0005[חלוקים]\u0006 חכמים עליו בנדרי זירוזין!","ודוחים: \u0003לא, לעולם\u0004 אפשר לומר כי דעת \u0003ר' אליעזר בן יעקב\u0004 היא, \u0003ו\u0004אולם \u0003מודה ר' אליעזר בהאי דנדרא הוי\u0004 \u0005[בזה שנדר הוא],\u0006 \u0003משום דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הנודר: \u0003לאו מלכא אנא, דמהנינא לך ואת לא מהנית לי\u0004 \u0005[אין אני מלך, שאני מהנה אותך ואתה אינך מהנה אותי],\u0006 ואין כוונתו לזירוז בלבד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא\u0004 \u0005[הזקן]\u0006 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003נדרי אונסין,\u0004 כגון ש\u0003הדירו חבירו שיאכל אצלו, וחלה הוא או חלה בנו או שעכבו נהר\u0004 ולא יכול היה לבוא — הרי אלה נדרי אונסין שאינם צריכים התרה. ונדייק: דווקא במקרים כאלה, ואולם \u0003הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא כן]\u0006 שלא אירע אונס — \u0003נדר הוא.\u0004 ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003ר' אליעזר בן יעקב —\u0004 הלא נדרי \u0003זירוזין הוי\u0004 \u0005[הם],\u0006 שלא התכוון לנדר כלל. \u0003אלא לאו רבנן\u0004 \u0005[האם לא\u0006 שיטת \u0005חכמים\u0006 היא\u0005].\u0006 \u0003ו\u0004נמצא כי \u0003פליגי\u0004 \u0005[חלוקים]\u0006 חכמים עליו!","ודחה רב אשי דבריו: \u0003לעולם\u0004 תאמר כי שיטת \u0003ר' אליעזר בן יעקב\u0004 היא, \u0003ומי סברת דאדריה מזמנא לזמינא\u0004 \u0005[והאם סבור אתה\u0006 שמדובר כאן \u0005שהדיר אותו המזמין למוזמן]?\u0006 \u0003לא,\u0004 כאן מדובר \u0003דזמינא אדריה למזמנא\u0004 \u0005[שהמוזמן הדיר את המזמין].\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מזמנת לי לסעודתיך\u0004 \u0005[מזמין אתה אותי לסעודתך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 המזמין: \u0003אין\u0004 \u0005[כן].\u0006 שאל אותו המוזמן: \u0003נדר זה עליך,\u0004 כלומר, האם נודר אתה בכך? \u0003ו\u0004אכן \u0003נדר. ו\u0004אז \u0003חלה הוא או שחלה בנו או שעכבו נהר — הרי אלו נדרי אונסין.\u0004 שכאן בא הדבר מצידו של המוזמן, ולא היתה כוונתו של המזמין לזרז את חבירו, ומשום כך אין זה בכלל נדרי זירוזין. ולכן אין היתר לנדר אלא כאשר אירע אונס בזה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה ששנינו: \u0003יתר על כן,\u0004 על האמור במשנתנו, \u0003אמר ר' אליעזר בן יעקב: האומר לחבירו \"קונם שאני נהנה לך\u0004 (ממך) \u0003אם אי\u0004 (אין) \u0003אתה מתארח אצלי ותאכל עמי פת חמה ותשתה עמי כוס חמין\", והלה הקפיד כנגדו\u0004 וכעס על שמכריחים אותו לעשות כן — \u0003אף אלו נדרי זירוזין. ולא הודו לו חכמים\u0004 בענין זה, שכיון שהשני מקפיד על כך, משמע שאין זה רק ביטוי של הפרזה אלא נדר ממש. ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא הודו לו חכמים\"? לאו\u0004 \u0005[האם לא]\u0006"],["\u0003אפילו בקמייתא\u0004 \u0005[ב\u0006דוגמאות \u0005הראשונות]\u0006 כשלא היתה הקפדה, הריהם חולקים בענין נדרי זירוזין, וסבורים שנדר הוא, \u0003ושמע מינה פליגי רבנן עליה\u0004 \u0005[ולמד מכאן\u0006 ש\u0005חולקים חכמים עליו].\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","ולגבי ענין ההלכה, שאותה לא ביררנו שואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על ההלכה בענין זה? ומביאים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ש\u0003אמר רב הונא: הלכה כר' אליעזר בן יעקב, וכן אמר רב אדא בר אהבה: הלכה כר' אליעזר בן יעקב.\u0004","\u0003נדרי הבאי\u0004 שאין בהם ממש, שהתירום חכמים, הריהם כגון אם \u0003אמר \"קונם אם לא ראיתי בדרך הזה\u0004 אנשים מרובים \u0003כעולי מצרים\",\u0004 או שאמר \u0003\"אם לא ראיתי נחש\u0004 גדול \u0003כקורת בית הבד\",\u0004 שלא התכוון לנדר, אלא הוא ביטוי של גוזמה, שרצה לאשר ולאמת דבר שהכל יודעים שאיננו נכון כמשמעו.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003נדרי הבאי — מותרין, שבועות הבאי — אסורין.\u0004 ששבועה היא ענין חמור, ואין אדם מוציא מפיו לשון שבועה אלא אם כן מתכוון להישבע ברצינות, וכיון שהדבר אינו נכון — אסור משום שבועת שוא.","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 הוא \u0005בדיוק]\u0006 \u0003שבועות הבאי? אילימא דאמר\u0004 \u0005[אם תאמר שאומר]\u0006 \u0003\"שבועה אם לא ראיתי בדרך הזה\u0004 כעולי מצרים \u0003\"\u0004— \u0003מידעם קאמר\u0004 \u0005[\u0006האם \u0005דבר אמר]?!\u0006 שהרי אין זה נוסח של שבועה ואין שבועה חלה עליו כלל, גם אם נתכוון לכך ברצינות.","\u0003אמר אביי:\u0004 הכוונה \u0003דאמר\u0004 \u0005[שאומר]\u0006 \u0003\"שבועה שראיתי\u0004 בדרך הזה כעולי מצרים \u0003\".\u0004 שאם לא ראה — הרי זה כנשבע לשקר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אם כן למה לי למימר\u0004 \u0005[לומר]\u0006 דבר זה? והרי אין בכך שום חידוש! \u0003ועוד: דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003נדר\u0004 השנוי במשנה \u0003קתני\u0004 \u0005[אמר],\u0006 וכפי שבנדר אומר \"אם לא ראיתי\" כך גם בשבועה! \u0003אלא אמר רבא, באומר\u0004 כך: \u0003\"יאסרו פירות העולם עלי בשבועה אם לא ראיתי בדרך הזה כעולי מצרים\".\u0004","לגופם של דברים \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ודלמא האי גברא\u0004 \u0005[ושמא אדם זה]\u0006 \u0003קינא דשומשמני חזא ואסיק להון שמא\u0004 \u0005[קן נמלים ראה וקרא להם\u0006 ב\u0005שם]\u0006 \u0003\"עולי מצרים\",\u0004 שראה נמלים רבות כעולי מצרים, \u0003ושפיר משתבע\u0004 \u0005[ויפה\u0006 הוא \u0005נשבע]\u0006 ומדוע אנו אומרים שזו שבועת הבאי?"],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003כי משתבע\u0004 \u0005[כאשר\u0006 אדם \u0005נשבע] —\u0006 \u0003אדעתא דידן משתבע\u0004 \u0005[על דעת שלנו,\u0006 של סתם בני אדם, הוא \u0005נשבע],\u0006 \u0003ואנן לא מסקינן נפשין אשומשמני\u0004 \u0005[ואנו איננו מעלים על דעתנו את הנמלים],\u0006 ואם הוא נשבע על כך, ודאי כוונתו לאנשים כעולי מצרים ממש.","ושואלים: \u0003ו\u0004כי \u0003על דעתא דנפשיה\u0004 \u0005[דעת עצמו]\u0006 \u0003לא עביד איניש דמשתבע\u0004 \u0005[אין אדם עשוי להישבע]?\u0006 וכי אין אדם עשוי להישבע כשיש לו במחשבתו תנאי או הגדרה מיוחדת על השבועה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשהן,\u0004 הדיינין, \u0003משביעין אותו\u0004 את המחוייב שבועה שפרע את חובו, \u0003אומרים לו: הוי יודע שלא על תנאי שבלבך אנו משביעין אותך,\u0004 כלומר, אין אתה יכול לסמוך על תנאי כלשהו שאתה עושה בליבך ולומר שאתה נשבע על פי תנאי זה, \u0003אלא על דעתינו ועל דעת בית דין.\u0004 ונברר: מה שאומרים לו \"על דעתינו\" \u0003לאפוקי מאי\u0004 \u0005[להוציא,\u0006 למעט \u0005מה]?\u0006 \u0003לאו לאפוקי דאסיק להו לאיסקונדרי\u0004 \u0005[האם לא להוציא,\u0006 מקרה \u0005שמעלה להם פסיפסים]\u0006 ונותנם לבעל חובו \u0003ואסיק להון שמא זוזי\u0004 \u0005[ומעלה,\u0006 קורא \u0005להם\u0006 בליבו ב\u0005שם זוזים,\u0006 מטבעות\u0005]\u0006 ונשבע שהחזיר מטבעות אלה, ולפי מה שמעלה בדעתו — נשבע באמת.","\u0003ומדקאמר\u0004 \u0005[וממה שאמר]\u0006 שמדגישים בהשבעה \u0003\"על דעתינו\", מכלל\u0004 הדברים אתה למד \u0003דעביד אינש דמשתבע אדעתא דנפשיה\u0004 \u0005[שעשוי אדם שישבע על דעת עצמו]\u0006 ושבועה זו יש בה ממש, ומשום כך כאשר משביעים אותו בבית דין צריך להוציא מכך!","ודוחים: \u0003לא,\u0004 הזהרה זו נאמרה כדי \u0003לאפוקי מקניא\u0004 \u0005[להוציא מן\u0006 המעשה של \u0005הקנה]\u0006 של \u0003רבא\u0004 וממעשים דוגמתו, בהם הנשבע אינו קורא לדברים שם לפי דעתו, אלא עושה מעשה שיש בו הטעיית בית הדין. וכך היה מעשה בקנה של רבא, \u0003דההוא גברא דהוה מסיק בחבריה זוזי\u0004 \u0005[שאדם אחד שהיה נושה בחבירו כסף]\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבא\u0004 לדין. \u0003אמר ליה\u0004 \u0005[לו]\u0006 המלווה \u0003ללוה: זיל\u0004 \u0005[לך]\u0006 \u0003פרע לי\u0004 את חובך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 הלווה: \u0003פרעתיך\u0004 כבר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אם כן, זיל אישתבע ליה דפרעתיה\u0004 \u0005[לך הישבע לו שפרעת לו].\u0006","\u0003אזל ואייתי קניא ויהיב זוזי בגויה\u0004 \u0005[הלך\u0006 אותו לווה \u0005והביא קנה\u0006 חלול \u0005ושם\u0006 את \u0005הכסף בתוכו]\u0006 \u0003והוה מסתמיך ואזיל ואתי עליה לבי דינא\u0004 \u0005[והיה נסמך והולך ובא עליו,\u0006 עם המקל הזה, \u0005לבית הדין].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003למלוה: נקוט האי קניא\u0004 \u0005[אחוז\u0006 את \u0005הקנה הזה]\u0006 \u0003בידך\u0004 כדי שאוכל להישבע וספר תורה בידי. נטל המלוה את המקל כדבריו ו\u0003נסב\u0004 \u0005[לקח]\u0006 הלווה \u0003ספר תורה ואישתבע דפרעיה\u0004 \u0005[ונשבע שפרע לו]\u0006 \u0003כל מה דהוה ליה בידיה\u0004 \u0005[שהיה לו בידו].\u0006","כששמע \u0003ההוא\u0004 \u0005[אותו]\u0006 \u0003מלוה\u0004 שהוא נשבע לשקר \u0003רגז ותברה לההוא קניא\u0004 \u0005[ושבר אותו קנה]\u0006 \u0003ואישתפך הנהו זוזי לארעא\u0004 \u0005[ונשפכו אותם המטבעות לארץ]\u0006 \u0003ואישתכח דקושטא אישתבע\u0004 \u0005[ונמצא שאמת נשבע],\u0006 שהרי החזיר לו את כל הכסף שהיה בקנה באותה שעה שנשבע. אבל היתה בכך הערמה, שהרי התכוון שהמלווה יחזיר לו את הקנה והכסף שבו לאחר השבועה. וכדי להימנע מהערמה כגון זו מזהירים את הנשבע שהוא נשבע על דעת בית דין.","ועדיין שואלים: \u0003ואכתי\u0004 \u0005[ו\u0006כי \u0005עדיין]\u0006 \u0003לא עביד דמישתבע אדעתא דנפשיה\u0004 \u0005[עשוי\u0006 אדם \u0005שיישבע על דעת עצמו]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003וכן מצינו במשה רבינו כשהשביע את ישראל בערבות מואב\u0004 שיקבלו על עצמם את התורה, \u0003אמר להם: הוו יודעים שלא על דעתכם אני משביע אתכם,\u0004 לפי תנאים שאתם עושים בליבכם, \u0003אלא על דעתי ועל דעת המקום, שנאמר: \"ולא אתכם לבדכם\u0004 אנכי כורת את הברית הזאת\u0003\"\u0004 (דברים כט, יג).","\u0003מאי\u0004 \u0005[מה]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003משה לישראל? לאו הכי קאמר להו\u0004 \u0005[\u0006האם \u0005לא כך אמר להם]:\u0006 \u0003דלמא עבידתון מילי\u0004 \u0005[שמא אתם עושים דברים\u0006 לא טובים, עבירות\u0005]\u0006 \u0003ואמריתון\u0004 \u0005[ואומרים]:\u0006 \u0003על דעתינו\u0004 היה דבר זה בזמן השבועה — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003על דעתי\u0004 אתם נשבעים. ונברר, \u0003לאפוקי מאי\u0004 \u0005[להוציא,\u0006 למעט את \u0005מה]\u0006 הזהירם? \u0003לאו לאפוקי דאסיקו שמא\u0004 \u0005[\u0006האם \u0005לא להוציא\u0006 אפשרות \u0005שמעלים שם,\u0006 שקוראים\u0005]\u0006 \u0003לעבודה זרה אלוה,\u0004 ואומרים שבליבם נשבעו על דעת כן, לעבוד אותה. \u0003מכלל\u0004 הדברים אתה למד \u0003דעביד איניש דמשתבע אדעתא דנפשיה\u0004 \u0005[שעשוי אדם שישבע על דעת עצמו]!\u0006","ודוחים: \u0003לא, עבודה זרה איקרי\u0004 \u0005[נקראת]\u0006 אף בדברי הכתוב \u0003אלוה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובכל אלהי מצרים\u0004 אעשה שפטים\u0003\"\u0004 (שמות יב, יב), ולכן חשש להם משה שמא הם מתכוונים לדבר זה. אבל אין בכך ענין של תנאי מיוחד שהם חושבים עליו בליבם, אלא של כוונה לא נכונה בשבועה עצמה.","ושואלים: מדוע נזקק משה לתנאי \"על דעתי\"? \u0003ולשבע יתהון\u0004 \u0005[ושישביע אותם]:\u0006 \u0003דמקיימיתון\u0004 \u0005[שאתם מקיימים]\u0006 \u0003מצות\u0004 וממילא נכלל בתוכן גם איסור עבודה זרה! ודוחים: \"מצוות\" \u0003משמע\u0004 אפשר לפרש גם \u0003מצות המלך,\u0004 ולהן הם מתכוונים ונשבעים.","ושואלים: \u0003ולשבע יתהון\u0004 \u0005[ושישביע אותם]:\u0006 \u0003דמקיימיתון\u0004 \u0005[שאתם מקיימים]\u0006 \u0003כל מצות!\u0004 ומשיבים: אפילו זה אינו מספיק, כי אפשר ש\u0003משמע\u0004 הדבר עבורם \u0003מצות ציצית,\u0004 שהרי \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003שקולה מצות ציצית כנגד כל מצות שבתורה\u0004 וכשקיבלו עליהם \"כל מצוות\" — למצות ציצית התכוונו.","ושואלים עוד: \u0003ולשבע יתהון\u0004 \u0005[ושישביע אותם]:\u0006 \u0003דמקיימיתון\u0004 \u0005[שאתם מקיימים]\u0006 \u0003תורה!\u0004 ודוחים: \u0003משמע תורה אחת,\u0004 שבכתב, ולא תורה שבעל פה. ושואלים: \u0003ולשבע יתהון\u0004 \u0005[ושישביע אותם]:\u0006 \u0003דמקיימיתון\u0004 \u0005[שאתם מקיימים]\u0006 \u0003תורות!\u0004 ואומרים: גם זה איננו כולל הכל, כי אפשר ש\u0003משמע תורת מנחה, תורת חטאת, תורת אשם.\u0004 ושואלים: אם כן \u0003ולשבע יתהון\u0004 \u0005[שישביע אותם]:\u0006 \u0003דמקיימיתון\u0004 \u0005[שאתם מקיימים]\u0006 \u0003[תורות] ומצות!\u0004 ודוחים: גם זה איננו כולל את כל התורה כולה, כי \u0003[תורות] משמע תורת המנחה וכו', מצות משמע מצות המלך.\u0004","ושואלים: \u0003ולישבע יתהון\u0004 \u0005[ושישביע אותם]:\u0006 \u0003דמקיימיתון\u0004 \u0005[שאתם מקיימים]\u0006 \u0003תורה כולה!\u0004 ומשיבים: \u0003תורה כולה משמע עבודה זרה,\u0004 כלומר, כפירה בעבודה זרה נקראת קיום תורה כולה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חמורה עבודה זרה, שכל הכופר בה — כאילו מודה בתורה כולה,\u0004 וכן להיפך. ולכן יכולים הם לומר ש\"תורה כולה\" היא ההתרחקות מעבודה זרה ולא יותר מכן.","ושואלים: \u0003ולישבע יתהון\u0004 \u0005[שישביע אותם]:\u0006 \u0003דמקיימיתון\u0004 \u0005[שאתם מקיימים]\u0006 התרחקות מ\u0003עבודה זרה ו\u0004כל ה\u0003תורה כולה, אי נמי\u0004 \u0005[או גם כן]:\u0006 שישביעם שהם מקיימים \u0003שש מאות ושלש עשרה מצות\u0004 ואז אין עוד ספק בדבר! \u0003אלא, משה רבינו מילתא דלא טריחא נקט\u0004 \u0005[דבר שאין\u0006 בו \u0005טירחה תפס],\u0006 שהיה יכול למצוא דרך אחרת להשביע אותם באופן שלא יהא כל ספק בדבר, אבל לא רצה לטרוח ולחפש דרך מסובכת ומורכבת, ולכן אמר להם שהוא משביעם על דעתו ועל דעת המקום.","שנינו במשנה שהנודר \u0003\"אם לא ראיתי נחש כקורת בית הבד\"\u0004 הרי זה נדר הבאי. ושואלים: \u0003ו\u0004כי \u0003לא\u0004 קיים נחש כזה? \u0003והא ההוא חויא דהוה בשני שבור מלכא\u0004 \u0005[והרי נחש אחד שהיה בשנותיו,\u0006 בזמנו \u0005של המלך שבור]\u0006 שהיה גדול כל כך ש\u0003רמו ליה תליסר אורוותא דתיבנא ובלע יתהון\u0004 \u0005[זרקו לו שלוש עשרה חבילות של תבן ובלע אותן]\u0006 ובודאי היה גדול מקורת בית הבד! \u0003אמר שמואל:\u0004 מדובר כאן \u0003בטרוף,\u0004 שנתכוון לומר שלנחש היו סדקים בגבו כמו קורת בית הבד. ומקשים: והרי \u0003כולהו נחשי מיטרף טרפי\u0004 \u0005[כל הנחשים\u0006 כולם יש \u0005בהם סדקים]\u0006 כאלה! ומשיבים: \u0003אגבו טרוף קאמרינן\u0004 \u0005[טרוף על גבו אנו אומרים]\u0006 וזה אינו מצוי כלל.","ושואלים: \u0003ולתני\u0004 \u0005[ושישנה]\u0006 בפירוש \u0003\"טרוף\",\u0004 ומדוע אמר \"כקורת בית הבד\"? ומשיבים: \u0003מילתא אגב אורחיה קא משמע לן\u0004 \u0005[דבר בדרך אגב השמיע לנו]\u0006 בכך, והוא ש\u0003קורת בית הבד גבו טרוף,\u0004 שצריכים להיות בקורה הזו סדקים סדקים. ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 לשם מה חשוב להודיענו זאת אם יש כך בקורת בית הבד? ומשיבים: \u0003למקח וממכר, לומר לך: המוכר קורת בית הבד לחבירו, אי\u0004 \u0005[אם]\u0006 \u0003גבו טרוף — אין\u0004 \u0005[כן]\u0006 מכר הוא, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 אם אין גבו טרוף, שאינה עשויה סדקים — \u0003לא\u0004 נקרא הדבר קורת בית הבד, אלא קורה סתם, ובטל המיקח."],["\u0003נדרי שגגות\u0004 עליהם שנינו שמותרים כיצד? נדר \u0003\"\u0004ככר זו אסורה עלי \u0003אם אכלתי ואם שתיתי\" ונזכר שאכל ושתה,\u0004 או שנדר \u0003\"שאני אוכל ושאני שותה\",\u0004 כלומר, אם יאכל ואם ישתה, \u0003ושכח ואכל ושתה. אמר \"קונם אשתי נהנית לי\u0004 משום \u0003שגנבה את כיסי\u0004 (ארנקי), או משום \u0003שהכתה את בני\" ונודע שלא הכתו,\u0004 או ש\u0003נודע שלא גנבה.\u0004","או סוג אחר של טעות — \u0003ראה אותן\u0004 אנשים באים לחצירו ו\u0003אוכלין תאנים,\u0004 ולא רצה שיאכלו מהן \u0003ואמר \"הרי\u0004 התאנים אסורות \u0003עליכם\u0004 כמו \u0003קרבן\" ונמצאו אביו ואחיו\u0004 ביניהם \u0003והיו עמהן אחרים,\u0004 שוודאי לא התכוון להדיר את אביו ואחיו. \u0003בית שמאי אומרים:\u0004 במקרה שנדר בלשון זו, \u0003הן,\u0004 אביו ואחיו שלא התכוון להדיר אותם — \u0003מותרים, ומה שעמהם,\u0004 שאר האנשים — \u0003אסורים. ובית הלל אומרים: אלו ואלו מותרין,\u0004 כאשר יבואר בגמרא.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כשם שנדרי שגגות מותרין, כך שבועות שגגות מותרות.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 הוא \u0005בדיוק]\u0006 \u0003שבועות שגגות? כגון\u0004 המעשה ב\u0003רב כהנא ורב אסי\u0004 שנחלקו בהלכה אחת, ומתוך הוויכוח \u0003הדין\u0004 \u0005[זה]\u0006 \u0003אמר: שבועתא דהכי\u0004 \u0005[שבועה שכך]\u0006 \u0003אמר רב\u0004 כמו שאני אומר, \u0003והדין\u0004 \u0005[וזה]\u0006 \u0003אמר: שבועתא דהכי\u0004 \u0005[שבועה שכך]\u0006 \u0003אמר רב\u0004 כמו שאני אומר. \u0003דכל חד וחד אדעתא דנפשיה שפיר קמישתבע\u0004 \u0005[שכל אחד ואחד על דעת עצמו יפה הוא נשבע],\u0006 כלומר, שהוא בטוח שכך היתה האמת, והרי שגגה היתה זו.","על מה ששנינו \u0003\"ראה אותן אוכלין\",\u0004 מביאים \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003פותחין בשבתות ובימים טובים,\u0004 שאם נדר אדם נדר להתענות, או שלא לאכול דבר מסויים — פותחים לו פתח להיתר משום השבתות והימים הטובים, שעל דעת ימים אלו ודאי לא נדר. \u0003בראשונה היו אומרים: אותן הימים,\u0004 שבתות וימים טובים שגילה דעתו שלא נתכוון לכוללם בנדר — \u0003מותרים, ושאר כל הימים\u0004 — \u0003אסורים, עד שבא ר' עקיבא ולימד: נדר שהותר מקצתו הותר כלו,\u0004 ומשום כך הותרו גם שאר הימים.","\u0003אמר רבה: דכולי עלמא\u0004 \u0005[ל\u0006דעת ה\u0005כל]\u0006 במשנתנו \u0003כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003אמר: אילו הייתי יודע שאבא ביניכם הייתי אומר \"כולכם אסורין חוץ מאבא\",\u0004 שבמקרה זה \u0003דכולהון\u0004 \u0005[שכולם]\u0006 \u0003אסורין ואביו מותר. לא נחלקו אלא באומר: אילו הייתי יודע שאבא ביניכם\u0004 אז \u0003הייתי אומר \"פלוני ופלוני\u0004 (האחרים) \u0003אסורין ואבא מותר\".\u0004"]]};
